:root {
  --ink: #07090b;
  --bone: #e9e2cf;
  --bone-dim: #a49e8e;
  --blood: #c1121f;
  --blood-hot: #ff2a37;
  --blood-dark: #5e0710;
  --rust: #a3471f;
  --acid: #d7ff4a;
  --panel: rgba(9, 13, 15, 0.82);
  --line: rgba(233, 226, 207, 0.2);
  --pixel-font: "Courier New", "Lucida Console", monospace;
  --display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  background: var(--ink);
  color: var(--bone);
  overflow: hidden;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--pixel-font);
  background:
    radial-gradient(circle at 50% 45%, #161d1c 0%, #090c0e 48%, #050607 100%);
}

#frame {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #080b0c;
  cursor: none;
  touch-action: none;
}

body.menu-open #game { cursor: default; }

/* ---------- global pixel overlays ---------- */

#fx-scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 8;
  opacity: 0.16;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.44) 2px,
    rgba(0, 0, 0, 0.44) 3px
  );
  mix-blend-mode: multiply;
}

#fx-grain {
  position: absolute;
  inset: -50%;
  pointer-events: none;
  z-index: 9;
  opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.9'/%3E%3C/svg%3E");
  animation: grain-jump 0.22s steps(2) infinite;
}

@keyframes grain-jump {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

#fx-damage {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 7;
  opacity: 0;
  transition: opacity 0.18s ease-out;
  background:
    radial-gradient(ellipse at center, transparent 28%, rgba(121, 0, 8, 0.36) 68%, rgba(100, 0, 5, 0.82) 100%);
  mix-blend-mode: multiply;
}
#fx-damage.hit { opacity: 1; transition: opacity 0.05s; }
#fx-damage.low { opacity: 0.72; animation: low-health 1.1s ease-in-out infinite; }
@keyframes low-health {
  0%, 100% { opacity: 0.42; }
  50% { opacity: 0.82; }
}

#fx-frenzy {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 6;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(180, 5, 18, 0.22) 100%);
  mix-blend-mode: screen;
  transition: opacity 0.2s;
}
#fx-frenzy.on { opacity: 1; animation: frenzy-pulse 0.34s steps(2) infinite; }
@keyframes frenzy-pulse {
  0%, 100% { filter: hue-rotate(0deg) saturate(1); }
  50% { filter: hue-rotate(-12deg) saturate(1.6); }
}

/* ---------- shared screen / title ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: clamp(16px, 2.4vh, 30px) clamp(20px, 4vw, 64px);
  background:
    radial-gradient(ellipse at 50% 47%, rgba(5, 8, 9, 0.06) 0%, rgba(5, 8, 9, 0.4) 54%, rgba(3, 4, 5, 0.92) 100%),
    linear-gradient(to bottom, rgba(3, 5, 6, 0.72), transparent 24%, transparent 70%, rgba(3, 5, 6, 0.8));
  opacity: 1;
  transition: opacity 0.38s ease, visibility 0.38s;
}
.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, transparent 0%, transparent 35%, rgba(0, 0, 0, 0.42) 100%);
}

.title-topline {
  position: relative;
  z-index: 2;
  width: 100%;
  display: flex;
  gap: 14px;
  justify-content: center;
  align-items: center;
  color: rgba(233, 226, 207, 0.45);
  font-size: clamp(7px, 0.8vw, 10px);
  letter-spacing: 0.22em;
  white-space: nowrap;
}
.title-topline .slash { color: var(--blood); }

.title-core {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  margin-top: -2vh;
  width: min(980px, 94vw);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #bcb6a6;
  font-size: clamp(8px, 0.9vw, 11px);
  letter-spacing: 0.36em;
  margin-bottom: clamp(6px, 1.2vh, 14px);
  text-shadow: 0 2px 0 #000;
}
.pulse-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  background: var(--blood-hot);
  box-shadow: 0 0 10px 2px rgba(255, 42, 55, 0.65);
  animation: dot-pulse 1.1s steps(2) infinite;
}
@keyframes dot-pulse { 50% { opacity: 0.2; } }

.logo {
  margin: 0;
  display: flex;
  flex-direction: column;
  line-height: 0.78;
  font-family: var(--display);
  font-weight: 900;
  letter-spacing: -0.045em;
  transform: scaleX(0.94);
  filter: drop-shadow(0 10px 0 rgba(0, 0, 0, 0.6));
}
.logo-line {
  display: block;
  font-size: clamp(48px, 11.4vw, 160px);
  white-space: nowrap;
}
.logo-white {
  color: #e9e2cf;
  text-shadow:
    3px 0 0 #151716,
    -3px 0 0 #151716,
    0 3px 0 #151716,
    0 -3px 0 #151716,
    8px 8px 0 rgba(0, 0, 0, 0.85);
}
.logo-red {
  position: relative;
  color: var(--blood);
  text-shadow:
    3px 0 0 #240207,
    -3px 0 0 #240207,
    0 3px 0 #240207,
    0 -3px 0 #240207,
    0 0 34px rgba(193, 18, 31, 0.38),
    8px 8px 0 rgba(0, 0, 0, 0.8);
  animation: sign-flicker 7s infinite;
}
.logo-red::before {
  content: attr(data-text);
  position: absolute;
  left: 0;
  top: 0;
  color: #ff5360;
  clip-path: polygon(0 18%, 100% 18%, 100% 26%, 0 26%);
  transform: translateX(-2px);
  opacity: 0.75;
}
.logo-red::after {
  content: "";
  position: absolute;
  left: 13%;
  top: 74%;
  width: 74%;
  height: 6%;
  background: var(--blood-dark);
  clip-path: polygon(0 0, 100% 20%, 92% 100%, 3% 80%);
  opacity: 0.7;
}
@keyframes sign-flicker {
  0%, 6%, 8%, 72%, 74%, 100% { opacity: 1; }
  7%, 73% { opacity: 0.58; }
}

.tagline {
  margin: clamp(10px, 2.1vh, 22px) 0 clamp(12px, 2.2vh, 24px);
  color: #a8a291;
  font-size: clamp(9px, 1.05vw, 13px);
  letter-spacing: 0.28em;
  line-height: 1.9;
  text-shadow: 0 2px 0 #000;
}
.tagline em {
  color: var(--bone);
  font-style: normal;
}

/* ---------- buttons ---------- */

.pixel-btn {
  position: relative;
  z-index: 3;
  appearance: none;
  border: 0;
  padding: 17px 38px 15px;
  min-width: 220px;
  color: var(--bone);
  background: #14191a;
  font-family: var(--pixel-font);
  font-weight: 700;
  font-size: clamp(12px, 1.2vw, 16px);
  letter-spacing: 0.26em;
  cursor: pointer;
  clip-path: polygon(0 8px, 8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px));
  box-shadow: inset 0 0 0 2px rgba(233, 226, 207, 0.22), 0 5px 0 rgba(0, 0, 0, 0.55);
  transition: transform 0.08s, background 0.12s, color 0.12s, box-shadow 0.12s;
  text-shadow: 0 2px 0 #000;
}
.pixel-btn::before,
.pixel-btn::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 7px;
  height: 7px;
  margin-top: -3px;
  background: currentColor;
  opacity: 0.6;
}
.pixel-btn::before { left: 12px; }
.pixel-btn::after { right: 12px; }
.pixel-btn:hover, .pixel-btn:focus-visible {
  background: var(--blood);
  color: #fff4e8;
  outline: none;
  box-shadow: inset 0 0 0 2px #ff6b73, 0 5px 0 #3b0308, 0 0 32px rgba(193, 18, 31, 0.45);
  transform: translateY(-1px);
}
.pixel-btn:active { transform: translateY(3px); box-shadow: inset 0 0 0 2px #ff6b73, 0 2px 0 #3b0308; }
.pixel-btn.primary {
  background: var(--blood);
  color: #fff0e0;
  box-shadow: inset 0 0 0 2px #ff5d66, 0 5px 0 #3a0207, 0 0 30px rgba(193, 18, 31, 0.3);
  animation: start-breathe 2.4s ease-in-out infinite;
}
.pixel-btn.primary:hover {
  background: #e71927;
  box-shadow: inset 0 0 0 2px #ffb0b4, 0 5px 0 #3a0207, 0 0 46px rgba(255, 42, 55, 0.62);
}
@keyframes start-breathe {
  0%, 100% { box-shadow: inset 0 0 0 2px #ff5d66, 0 5px 0 #3a0207, 0 0 24px rgba(193, 18, 31, 0.22); }
  50% { box-shadow: inset 0 0 0 2px #ff8b91, 0 5px 0 #3a0207, 0 0 42px rgba(255, 42, 55, 0.48); }
}

/* ---------- title controls ---------- */

.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 18px;
  max-width: 840px;
  margin-top: clamp(15px, 2.8vh, 30px);
  padding-top: clamp(10px, 1.8vh, 18px);
  border-top: 1px solid rgba(233, 226, 207, 0.12);
}
.control {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #8e8a7d;
  font-size: clamp(7px, 0.72vw, 9px);
  letter-spacing: 0.16em;
  white-space: nowrap;
}
.keys { display: flex; gap: 3px; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  color: #d9d2c0;
  background: #181d1e;
  border: 1px solid rgba(233, 226, 207, 0.28);
  border-bottom-width: 2px;
  font-family: var(--pixel-font);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.6);
}
kbd.wide { padding: 0 6px; }

.content-note {
  margin: clamp(10px, 1.8vh, 18px) 0 0;
  color: #625f56;
  font-size: clamp(7px, 0.7vw, 9px);
  letter-spacing: 0.14em;
}
.warn {
  display: inline-block;
  padding: 2px 4px;
  margin-right: 4px;
  background: var(--blood);
  color: #fff;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.title-footer {
  position: relative;
  z-index: 2;
  width: 100%;
  display: flex;
  justify-content: space-between;
  color: rgba(233, 226, 207, 0.28);
  font-size: clamp(6px, 0.66vw, 8px);
  letter-spacing: 0.16em;
}
.blink { color: rgba(193, 18, 31, 0.7); animation: blink 1.2s steps(2) infinite; }
@keyframes blink { 50% { opacity: 0; } }

/* ---------- modals ---------- */

#gameover-screen, #pause-screen {
  justify-content: center;
  background: rgba(3, 5, 6, 0.7);
  backdrop-filter: blur(2px);
}
.modal {
  position: relative;
  z-index: 2;
  width: min(540px, 92vw);
  padding: clamp(24px, 4vh, 44px) clamp(22px, 4vw, 52px);
  text-align: center;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.04) 0 2px, transparent 2px 8px),
    rgba(8, 12, 13, 0.92);
  border: 1px solid rgba(233, 226, 207, 0.2);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.7), inset 0 0 0 5px rgba(0, 0, 0, 0.35);
  clip-path: polygon(0 14px, 14px 0, calc(100% - 14px) 0, 100% 14px, 100% calc(100% - 14px), calc(100% - 14px) 100%, 14px 100%, 0 calc(100% - 14px));
}
.modal.compact { width: min(430px, 92vw); }
.modal-kicker {
  color: var(--blood);
  font-size: 9px;
  letter-spacing: 0.38em;
  margin-bottom: 12px;
}
.dead-title, .pause-title {
  margin: 0;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(38px, 6vw, 70px);
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: #e9e2cf;
  text-shadow: 3px 3px 0 #1a0407, 0 0 30px rgba(193, 18, 31, 0.25);
}
.dead-title { color: var(--blood); text-shadow: 3px 3px 0 #230207, 0 0 32px rgba(255, 42, 55, 0.26); }
.dead-sub {
  color: #8f8a7c;
  font-size: 9px;
  letter-spacing: 0.14em;
  margin: 14px 0 22px;
}
.stat-grid {
