  };

  const cam = CR.cam = { x: 0, y: 0 };

  CR.zombies = [];
  CR.corpses = [];
  CR.particles = [];
  CR.gibs = [];
  CR.floaters = [];
  CR.pickups = [];
  CR.afterimages = [];
  CR.screenDrops = [];
  CR.rain = [];
  CR.props = [];
  CR.lights = [];
  CR.decorCorpses = [];

  // ------------------------------------------------------------
