    CR.rain.length = 0;
    const n = Math.round(CR.view.w * CR.view.h / 1500);
    for (let i = 0; i < n; i++) {
      CR.rain.push({
        x: rand(0, CR.view.w), y: rand(0, CR.view.h),
        len: rand(3, 8), speed: rand(130, 230), a: rand(0.12, 0.35)
      });
