    for (const f of CR.fog) {
      f.x += f.vx * dt;
      f.y += f.vy * dt;
      if (f.x > world.w + 120) f.x = -120;
      if (f.x < -120) f.x = world.w + 120;
      if (f.y > world.h + 80) f.y = -80;
