(() => {
  'use strict';
  const CR = window.CR;
  const {
    TAU, clamp, lerp, rand, randInt, pick, dist, angleDiff, approach,
    input, state, cam, world, view
  } = CR;

  const ZTYPES = {
    walker: { hp: 26, speed: 27, radius: 7, damage: 9, scale: 1.0, score: 100 },
    runner: { hp: 17, speed: 57, radius: 6, damage: 7, scale: 0.92, score: 150 },
    brute: { hp: 88, speed: 19, radius: 11, damage: 18, scale: 1.42, score: 320 },
    boss: { hp: 680, speed: 15, radius: 20, damage: 27, scale: 2.05, score: 2800 }
  };

  const player = CR.player = {
    x: 800, y: 520, vx: 0, vy: 0, radius: 7,
    aim: 0, moveAngle: 0, walkPhase: 0, moving: false,
    hp: 100, maxHp: 100, speed: 134,
    attack: false, rev: 0, bladePhase: 0, attackTick: 0, swing: 0,
    dashTime: 0, dashCd: 0, dashX: 0, dashY: 0,
    invuln: 0, hurtFlash: 0, dead: false,
    frenzy: 0, frenzyTime: 0, kills: 0,
    exhaust: 0, step: 0
  };

  CR.buildDecor = function () {
    CR.decorCorpses.length = 0;
    CR.decorCorpses.push(
      { x: 724, y: 560, angle: 0.8, scale: 1.0, kind: 'ripped', life: Infinity, static: true },
      { x: 860, y: 474, angle: 2.45, scale: 0.95, kind: 'gutted', life: Infinity, static: true },
      { x: 646, y: 468, angle: -0.35, scale: 0.9, kind: 'crawler', life: Infinity, static: true },
      { x: 944, y: 592, angle: 1.9, scale: 1.05, kind: 'ripped', life: Infinity, static: true },
      { x: 1098, y: 542, angle: -1.3, scale: 0.8, kind: 'gutted', life: Infinity, static: true }
    );
  };

  CR.resetGame = function () {
    CR.zombies.length = 0;
    CR.particles.length = 0;
    CR.gibs.length = 0;
    CR.floaters.length = 0;
    CR.pickups.length = 0;
    CR.afterimages.length = 0;
    CR.screenDrops.length = 0;
    CR.corpses.length = 0;
    CR.resetDecals();

    const p = player;
    p.x = 800; p.y = 520; p.vx = 0; p.vy = 0; p.radius = 7;
    p.aim = -0.2; p.moveAngle = 0; p.walkPhase = 0; p.moving = false;
    p.hp = 100; p.maxHp = 100; p.speed = 134;
    p.attack = false; p.rev = 0; p.bladePhase = 0; p.attackTick = 0; p.swing = 0;
    p.dashTime = 0; p.dashCd = 0; p.dashX = 0; p.dashY = 0;
    p.invuln = 0; p.hurtFlash = 0; p.dead = false;
    p.frenzy = 0; p.frenzyTime = 0; p.kills = 0;
    p.exhaust = 0; p.step = 0;

    state.wave = 0;
    state.waveState = 'idle';
    state.waveTimer = 0;
    state.spawnTimer = 0;
    state.spawnQueue.length = 0;
    state.remaining = 0;
    state.score = 0;
    state.kills = 0;
    state.combo = 0;
    state.comboTimer = 0;
    state.bestCombo = 0;
    state.boss = null;
    state.announce = null;
    state.flash = 0;
    state.whiteFlash = 0;
    state.hitstop = 0;
    state.slowmo = 0;
    state.shake = 0;
    state.damageFlash = 0;
    state.lowHealth = false;
    state.gameTime = 0;
    state.deaths = 0;
    state.totalGore = 0;
    state.bannerTimer = 0;
    state.mode = 'playing';
    state.started = true;
    state.menuCamera = 0;

    cam.x = clamp(p.x - view.w / 2, 0, world.w - view.w);
    cam.y = clamp(p.y - view.h / 2, 0, world.h - view.h);

    CR.dom.damage.classList.remove('low', 'hit');
    CR.dom.frenzy.classList.remove('on');
    CR.dom.gameover.classList.add('hidden');
    CR.dom.pause.classList.add('hidden');
    document.body.classList.remove('menu-open');

    CR.startWave(1);
    if (CR.sound) {
      CR.sound.unlock();
      CR.sound.started = true;
    }
  };

  CR.startWave = function (n) {
    state.wave = n;
    state.waveState = 'active';
    state.waveTimer = 0;
    state.spawnTimer = 0;
    state.spawnQueue.length = 0;
    state.boss = null;

    const isBoss = n % 5 === 0;
    const count = Math.min(34, 4 + Math.ceil(n * 1.65));
    for (let i = 0; i < count; i++) {
      let type = 'walker';
      const roll = Math.random();
      if (n >= 2 && roll < Math.min(0.28, 0.08 + n * 0.022)) type = 'runner';
      if (n >= 3 && roll > 0.86 - Math.min(0.12, n * 0.008)) type = 'brute';
      state.spawnQueue.push(type);
    }
    if (isBoss) state.spawnQueue.push('boss');

    // First few are close enough to read immediately.
    const first = isBoss ? 3 : Math.min(4, state.spawnQueue.length);
    for (let i = 0; i < first; i++) {
      const type = state.spawnQueue.shift();
      CR.spawnZombie(type, true);
    }
    state.remaining = state.spawnQueue.length + CR.zombies.length;

    const names = [
      'THE YARD', 'MEAT LOCKER', 'BLOOD RUN', 'THE KILL FLOOR', 'ABATTOIR PROTOCOL',
      'RUST & ROT', 'NIGHT SHIFT', 'THE GRINDER', 'BONE ORCHARD', 'FINAL CUT'
    ];
    const sub = isBoss ? 'ABATTOIR PROTOCOL // KILL THE BIG ONE' : names[(n - 1) % names.length];
    CR.announce(`WAVE ${String(n).padStart(2, '0')}`, sub, isBoss ? 3.2 : 2.6);
    if (CR.sound) CR.sound.wave();
  };

  CR.announce = function (title, sub, time = 2.4) {
    state.announce = { title, sub, time, max: time };
  };

  CR.spawnZombie = function (type, near = false) {
    const def = ZTYPES[type] || ZTYPES.walker;
    let x = player.x, y = player.y;
    for (let tries = 0; tries < 60; tries++) {
      const a = rand(0, TAU);
      const d = near ? rand(112, 185) : rand(245, 390);
      x = clamp(player.x + Math.cos(a) * d, 55, world.w - 55);
      y = clamp(player.y + Math.sin(a) * d, 55, world.h - 55);
      if (!CR.isBlocked(x, y, def.radius + 5)) break;
    }
    if (CR.isBlocked(x, y, def.radius + 2)) {
      x = clamp(player.x + rand(-150, 150), 55, world.w - 55);
      y = clamp(player.y + rand(-120, 120), 55, world.h - 55);
    }
    const waveScale = 1 + (state.wave - 1) * 0.115;
    const z = {
      type, x, y, vx: 0, vy: 0,
      radius: def.radius, scale: def.scale,
      hp: def.hp * waveScale, maxHp: def.hp * waveScale,
      speed: def.speed * (1 + Math.min(0.32, state.wave * 0.014)),
      damage: def.damage * (1 + Math.min(0.5, state.wave * 0.028)),
      score: def.score,
      angle: rand(0, TAU), phase: rand(0, TAU), seed: rand(0, 100),
      limbs: { armL: true, armR: true, head: true, legL: true, legR: true },
      attackCd: rand(0.6, 1.7), swipe: 0, stagger: 0, flash: 0,
      dead: false, slow: 1, growlCd: rand(2, 7), lunge: 0, hurtTint: 0,
      boss: type === 'boss'
    };
    CR.zombies.push(z);
    if (type === 'boss') {
      state.boss = z;
      CR.announce('ABATTOIR', 'THE BIG ONE IS HUNGRY', 3.2);
      state.shake = 7;
      state.flash = 0.6;
    }
    // dirt burst at spawn
    for (let i = 0; i < 10; i++) {
      CR.particles.push({
        type: 'dirt', x, y, z: rand(0, 3), vx: rand(-30, 30), vy: rand(-30, 30), vz: rand(8, 38),
        life: rand(0.4, 1.1), max: 1.1, size: rand(1, 3), color: pick(['#3b3422', '#282317', '#4a3b25'])
      });
    }
    if (near) {
      for (let i = 0; i < 5; i++) {
        CR.particles.push({
          type: 'smoke', x, y, z: rand(0, 8), vx: rand(-8, 8), vy: rand(-8, 8), vz: rand(5, 16),
          life: rand(0.5, 1.2), max: 1.2, size: rand(2, 5), color: '#131810'
        });
      }
    }
    if (Math.random() < 0.35) CR.sound.growl();
    return z;
  };

  // ------------------------------------------------------------
  //  player update
  // ------------------------------------------------------------
  function updatePlayer(dt) {
    const p = player;
    if (p.dead) {
      p.vx *= Math.pow(0.001, dt);
      p.vy *= Math.pow(0.001, dt);
      p.x += p.vx * dt; p.y += p.vy * dt;
      return;
    }

    let ix = 0, iy = 0;
    if (input.keys.has('a') || input.keys.has('ArrowLeft')) ix -= 1;
    if (input.keys.has('d') || input.keys.has('ArrowRight')) ix += 1;
    if (input.keys.has('w') || input.keys.has('ArrowUp')) iy -= 1;
    if (input.keys.has('s') || input.keys.has('ArrowDown')) iy += 1;
    if (input.touch.active) {
      ix += input.touch.dx;
      iy += input.touch.dy;
    }
    let mag = Math.hypot(ix, iy);
    if (mag > 1) { ix /= mag; iy /= mag; mag = 1; }
    p.moving = mag > 0.08;

    // aim
    const mwx = cam.x + input.mouse.x;
    const mwy = cam.y + input.mouse.y;
    let aimTarget = Math.atan2(mwy - p.y, mwx - p.x);
    if (input.touch.active && !input.mouse.inside) {
      let best = null, bestD = 260;
      for (const z of CR.zombies) {
        if (z.dead) continue;
        const d = dist(p.x, p.y, z.x, z.y);
        if (d < bestD) { bestD = d; best = z; }
      }
      if (best) aimTarget = Math.atan2(best.y - p.y, best.x - p.x);
      else if (p.moving) aimTarget = Math.atan2(iy, ix);
    }
    p.aim = p.aim + angleDiff(aimTarget, p.aim) * Math.min(1, dt * 24);

    if (p.moving) {
      p.moveAngle = Math.atan2(iy, ix);
      p.walkPhase += dt * (8 + Math.hypot(p.vx, p.vy) * 0.025);
      p.step += dt * (7 + Math.hypot(p.vx, p.vy) * 0.03);
    } else {
      p.walkPhase += dt * 1.6;
    }

    // dash
    p.dashCd = Math.max(0, p.dashCd - dt);
    const dashPressed = input.pressed.has('Shift') || input.pressed.has('shift') || input.touch.dash;
    if (dashPressed && p.dashCd <= 0) {
      let dx = ix, dy = iy;
      if (mag < 0.1) { dx = Math.cos(p.aim); dy = Math.sin(p.aim); }
      const m = Math.hypot(dx, dy) || 1;
      p.dashX = dx / m; p.dashY = dy / m;
      p.dashTime = 0.16;
      p.dashCd = 0.82;
      p.invuln = Math.max(p.invuln, 0.3);
      p.hurtFlash = 0;
      if (CR.sound) CR.sound.dash();
      for (let i = 0; i < 9; i++) {
        CR.particles.push({
          type: 'dust', x: p.x + rand(-6, 6), y: p.y + rand(-6, 6), z: rand(0, 3),
          vx: -p.dashX * rand(15, 55) + rand(-15, 15), vy: -p.dashY * rand(15, 55) + rand(-15, 15),
          vz: rand(4, 18), life: rand(0.25, 0.55), max: 0.55, size: rand(2, 4), color: pick(['#4b4734', '#2d2c21', '#5b5541'])
        });
      }
    }
    input.touch.dash = false;

    if (p.dashTime > 0) {
      p.dashTime -= dt;
      p.vx = p.dashX * 520;
      p.vy = p.dashY * 520;
      p.invuln = Math.max(p.invuln, 0.1);
      if (Math.random() < 0.8) {
        CR.afterimages.push({ x: p.x, y: p.y, angle: p.aim, life: 0.24, max: 0.24 });
      }
    } else {
      const maxSpeed = p.speed * (p.attack ? 0.72 : 1) * (p.frenzyTime > 0 ? 1.12 : 1);
      const accel = 980;
      p.vx = approach(p.vx, ix * maxSpeed, accel * dt);
      p.vy = approach(p.vy, iy * maxSpeed, accel * dt);
      if (!p.moving) {
        p.vx *= Math.pow(0.0001, dt);
        p.vy *= Math.pow(0.0001, dt);
      }
    }

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    CR.resolveProps(p);

    // chainsaw
    const wantsAttack = input.mouse.down || input.keys.has(' ') || input.touch.attack;
    p.attack = wantsAttack;
    if (wantsAttack) {
      p.rev = Math.min(1, p.rev + dt * 7.5);
      p.bladePhase += dt * (18 + p.rev * 52);
      p.attackTick -= dt;
      if (p.rev > 0.22 && p.attackTick <= 0) {
        p.attackTick = p.frenzyTime > 0 ? 0.052 : 0.082;
        doChainsawHit();
      }
      p.swing = Math.min(1, p.swing + dt * 8);
    } else {
      p.rev = Math.max(0, p.rev - dt * 5);
      p.attackTick = 0;
      p.swing = Math.max(0, p.swing - dt * 7);
    }

    // chainsaw exhaust
    p.exhaust -= dt;
    if (p.rev > 0.35 && p.exhaust <= 0) {
      p.exhaust = rand(0.05, 0.14);
      const a = p.aim + Math.PI + rand(-0.3, 0.3);
      CR.particles.push({
        type: 'smoke', x: p.x + Math.cos(a) * 9, y: p.y + Math.sin(a) * 9, z: rand(2, 6),
        vx: Math.cos(a) * rand(6, 20) + rand(-4, 4), vy: Math.sin(a) * rand(6, 20) + rand(-4, 4),
        vz: rand(8, 20), life: rand(0.35, 0.8), max: 0.8, size: rand(2, 4), color: pick(['#6a6658', '#49463c', '#2e2d27'])
      });
    }

    p.invuln = Math.max(0, p.invuln - dt);
    p.hurtFlash = Math.max(0, p.hurtFlash - dt * 3.2);
    p.frenzyTime = Math.max(0, p.frenzyTime - dt);
    if (p.frenzyTime <= 0 && p.frenzy > 0) p.frenzy = Math.max(0, p.frenzy - dt * 1.6);
    if (p.frenzyTime > 0) {
      p.frenzy = 100;
      if (CR.sound) CR.sound.saw(p.rev, p.attack);
    }
    if (p.frenzy >= 100 && (input.pressed.has('q') || input.pressed.has('Q'))) {
      p.frenzyTime = 8;
      p.frenzy = 100;
      state.flash = 0.7;
      state.shake = 8;
      CR.announce('BLOOD FRENZY', 'RIP AND TEAR UNTIL IT STOPS MOVING', 2.4);
      if (CR.sound) CR.sound.frenzy();
    }
    CR.dom.frenzy.classList.toggle('on', p.frenzyTime > 0);
    if (CR.sound) CR.sound.saw(p.rev, p.attack);
  }

  function doChainsawHit() {
    const p = player;
    const frenzy = p.frenzyTime > 0;
    const range = 31 + p.rev * 5 + (frenzy ? 7 : 0);
    const arc = 0.88 + (frenzy ? 0.22 : 0);
    const dmg = (8 + p.rev * 5 + (frenzy ? 7 : 0)) * rand(0.86, 1.14);
    let hitAny = false;

    for (const z of CR.zombies) {
      if (z.dead) continue;
      const d = dist(p.x, p.y, z.x, z.y);
      if (d > range + z.radius) continue;
      const a = Math.atan2(z.y - p.y, z.x - p.x);
      if (Math.abs(angleDiff(a, p.aim)) > arc) continue;
      hitAny = true;
      damageZombie(z, dmg, p.aim, d);
    }

    if (hitAny) {
      p.swing = 1;
      state.hitstop = Math.max(state.hitstop, 0.018);
      state.shake = Math.max(state.shake, 2.2);
      state.flash = Math.max(state.flash, 0.12);
      if (CR.sound) CR.sound.hit();
      // spray from the blade tip
      const bx = p.x + Math.cos(p.aim) * (range * 0.7);
      const by = p.y + Math.sin(p.aim) * (range * 0.7);
      for (let i = 0; i < 5; i++) {
        CR.particles.push({
          type: 'spark', x: bx + rand(-4, 4), y: by + rand(-4, 4), z: rand(1, 5),
          vx: Math.cos(p.aim + rand(-1.2, 1.2)) * rand(20, 80), vy: Math.sin(p.aim + rand(-1.2, 1.2)) * rand(20, 80),
          vz: rand(10, 50), life: rand(0.15, 0.4), max: 0.4, size: 1, color: pick(['#ffd166', '#ff8a2b', '#fff1b8'])
        });
      }
    }
  }

  function damageZombie(z, dmg, dir, distance) {
    if (z.dead) return;
    const p = player;
    z.hp -= dmg;
    z.flash = 0.13;
    z.stagger = Math.max(z.stagger, 0.13);
    z.vx += Math.cos(dir) * 80;
    z.vy += Math.sin(dir) * 80;

    const hx = z.x - Math.cos(dir) * z.radius * 0.35;
    const hy = z.y - Math.sin(dir) * z.radius * 0.35;
    spawnBlood(hx, hy, dir, 7 + Math.round(dmg * 0.8), 1 + dmg * 0.01);
    CR.addSplat(hx, hy, dir, 5, 0.42, 0.55);

    if (CR.sound && Math.random() < 0.55) CR.sound.splat();

    if (z.hp <= 0) {
      killZombie(z, dir);
      return;
    }

    // dismemberment
    const roll = Math.random();
    if (z.limbs.head && roll < 0.025) {
      z.limbs.head = false;
      z.hp = 0;
      CR.addFloater('DECAP +100', z.x, z.y - 16, '#ff5a5f', 1);
      state.score += 100;
      state.totalGore += 1;
      spawnGib(z.x, z.y, dir, 120, 'head', 1.2);
      spawnBlood(z.x, z.y, dir, 30, 1.5);
      killZombie(z, dir);
      return;
    }
    if (z.limbs.armL && roll < 0.075) {
      z.limbs.armL = false;
      CR.addFloater('DISARMED +40', z.x, z.y - 14, '#ffb15c', 1);
      state.score += 40;
      state.totalGore += 1;
      spawnGib(z.x, z.y, dir + rand(-0.7, 0.7), 140, 'arm', 1.1);
      spawnBlood(z.x, z.y, dir + rand(-0.6, 0.6), 20, 1.25);
      state.shake = Math.max(state.shake, 3);
      state.hitstop = Math.max(state.hitstop, 0.035);
      if (CR.sound) CR.sound.dismember();
    } else if (z.limbs.armR && roll < 0.12) {
      z.limbs.armR = false;
      CR.addFloater('DISARMED +40', z.x, z.y - 14, '#ffb15c', 1);
      state.score += 40;
      state.totalGore += 1;
      spawnGib(z.x, z.y, dir + rand(-0.7, 0.7), 140, 'arm', 1.1);
      spawnBlood(z.x, z.y, dir + rand(-0.6, 0.6), 20, 1.25);
      state.shake = Math.max(state.shake, 3);
      state.hitstop = Math.max(state.hitstop, 0.035);
      if (CR.sound) CR.sound.dismember();
    } else if (z.limbs.legL && roll < 0.155) {
      z.limbs.legL = false;
      z.speed *= 0.55;
      z.limbs.legR = false;
      CR.addFloater('HAMSTRUNG +30', z.x, z.y - 14, '#ffd166', 1);
      state.score += 30;
      state.totalGore += 1;
      spawnGib(z.x, z.y, dir + rand(-0.9, 0.9), 110, 'leg', 1.0);
      spawnBlood(z.x, z.y, dir, 16, 1.1);
    }
  }

  function killZombie(z, dir) {
    if (z.dead) return;
    z.dead = true;
    const p = player;
    const base = z.score || 100;

    state.combo += 1;
    state.comboTimer = 3.4;
    state.bestCombo = Math.max(state.bestCombo, state.combo);
    state.kills += 1;
    p.kills += 1;
    state.totalGore += 4 + Math.round(z.scale * 2);

    const mult = 1 + Math.min(4, (state.combo - 1) * 0.18);
    const gained = Math.round(base * mult);
    state.score += gained;
    CR.addFloater(`+${gained}`, z.x, z.y - 14, state.combo > 3 ? '#ffd166' : '#e9e2cf', state.combo > 6 ? 2 : 1);
    if (state.combo >= 5 && state.combo % 5 === 0) {
      CR.addFloater(state.combo >= 20 ? 'CARNAGE!' : 'MASSACRE!', p.x, p.y - 34, '#ff3b43', 2);
    }

    p.frenzy = Math.min(100, p.frenzy + 10 + z.scale * 2);
    if (p.frenzy >= 100 && p.frenzyTime <= 0) {
      CR.addFloater('FRENZY READY // Q', p.x, p.y - 42, '#d7ff4a', 1);
    }

    // gore explosion
    const n = z.boss ? 34 : Math.round(9 + z.scale * 5);
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU);
      const power = rand(30, 180) * (z.boss ? 1.7 : 1);
      CR.gibs.push({
        type: pick(['meat', 'meat', 'meat', 'bone', 'cloth', 'tooth', 'eye']),
        x: z.x + rand(-3, 3), y: z.y + rand(-3, 3),
        z: rand(3, 16), vx: Math.cos(a) * power + Math.cos(dir) * 30,
        vy: Math.sin(a) * power + Math.sin(dir) * 30,
        vz: rand(40, 130), rot: rand(0, TAU), vr: rand(-8, 8),
        size: rand(1.2, 3.4) * z.scale, life: rand(7, 18), max: 18,
        grounded: false, color: pick(['#7d0a12', '#9d0e18', '#5b070d', '#c41723'])
      });
    }
    for (const key of ['armL', 'armR', 'legL', 'legR', 'head']) {
      if (z.limbs[key]) {
        CR.gibs.push({
          type: key === 'head' ? 'head' : key.startsWith('arm') ? 'arm' : 'leg',
          x: z.x, y: z.y, z: rand(5, 12),
          vx: Math.cos(dir + rand(-0.9, 0.9)) * rand(60, 160),
          vy: Math.sin(dir + rand(-0.9, 0.9)) * rand(60, 160),
          vz: rand(50, 110), rot: rand(0, TAU), vr: rand(-5, 5),
          size: z.scale, life: rand(10, 20), max: 20, grounded: false
        });
      }
    }
    spawnBlood(z.x, z.y, dir, z.boss ? 90 : 34, z.boss ? 2.2 : 1.35);
    CR.addPool(z.x, z.y, z.boss ? 40 : 14 + z.scale * 6, 0.9);
    CR.addSplat(z.x, z.y, dir, z.boss ? 40 : 16, z.boss ? 1.8 : 0.9, 0.9);
    CR.corpses.push({
      x: z.x, y: z.y, angle: z.angle + rand(-0.4, 0.4),
      scale: z.scale, kind: 'ripped', life: 42, max: 42, static: false
    });

    if (Math.random() < (z.boss ? 1 : 0.075)) {
      CR.pickups.push({
        type: 'medkit', x: z.x + rand(-5, 5), y: z.y + rand(-5, 5),
        life: 22, bob: rand(0, TAU)
      });
    }
    if (Math.random() < 0.05) {
      CR.pickups.push({
        type: 'adrenaline', x: z.x + rand(-5, 5), y: z.y + rand(-5, 5),
        life: 20, bob: rand(0, TAU)
      });
    }

    state.shake = Math.max(state.shake, z.boss ? 12 : 4.2);
    state.hitstop = Math.max(state.hitstop, z.boss ? 0.16 : 0.05);
    state.flash = Math.max(state.flash, z.boss ? 1 : 0.2);
    if (z.boss) {
      state.slowmo = 1.2;
      state.whiteFlash = 0.9;
      state.boss = null;
      CR.announce('ABATTOIR DOWN', 'THE MEAT KEEPS COMING', 2.6);
      if (CR.sound) CR.sound.death();
    } else if (CR.sound) {
      CR.sound.splat();
      if (Math.random() < 0.5) CR.sound.dismember();
    }

    if (state.kills % 10 === 0) {
      CR.addFloater(`${state.kills} DEAD`, p.x, p.y - 46, '#ff5a5f', 2);
    }
  }

  function spawnBlood(x, y, dir, count, power = 1) {
    for (let i = 0; i < count; i++) {
      const a = dir + rand(-0.65, 0.65);
      const sp = rand(20, 150) * power;
      CR.particles.push({
        type: 'blood', x: x + rand(-2, 2), y: y + rand(-2, 2),
        z: rand(1, 8), vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        vz: rand(20, 100) * power, life: rand(0.3, 1.0), max: 1.0,
        size: rand(1, 2.6), color: pick(['#8d0d16', '#b9121f', '#6a0710', '#d21c29'])
      });
    }
    // mist
    for (let i = 0; i < Math.min(6, count * 0.25); i++) {
      CR.particles.push({
        type: 'mist', x, y, z: rand(1, 8), vx: rand(-20, 20), vy: rand(-20, 20),
        vz: rand(0, 18), life: rand(0.2, 0.55), max: 0.55, size: rand(2, 5),
        color: 'rgba(111,8,17,0.5)'
      });
    }
  }

  function spawnGib(x, y, dir, speed, type, scale = 1) {
    CR.gibs.push({
      type, x, y, z: rand(4, 10),
      vx: Math.cos(dir) * speed + rand(-20, 20),
      vy: Math.sin(dir) * speed + rand(-20, 20),
      vz: rand(40, 100), rot: rand(0, TAU), vr: rand(-7, 7),
      size: scale, life: rand(10, 18), max: 18, grounded: false
    });
  }

  // ------------------------------------------------------------
  //  zombies
  // ------------------------------------------------------------
  function updateZombies(dt) {
    const p = player;
    const list = CR.zombies;
    for (const z of list) {
      if (z.dead) continue;
      z.flash = Math.max(0, z.flash - dt);
      z.swipe = Math.max(0, z.swipe - dt);
      z.growlCd -= dt;
      if (z.growlCd <= 0) {
        z.growlCd = rand(4, 10);
        if (Math.random() < 0.4 && CR.sound) CR.sound.growl();
      }

      if (z.stagger > 0) {
        z.stagger -= dt;
        z.x += z.vx * dt;
        z.y += z.vy * dt;
        z.vx *= Math.pow(0.001, dt);
        z.vy *= Math.pow(0.001, dt);
        CR.resolveProps(z);
        continue;
      }

      const dx = p.x - z.x, dy = p.y - z.y;
      const d = Math.hypot(dx, dy) || 1;
      let target = Math.atan2(dy, dx);
      const wobble = Math.sin(state.time * 1.7 + z.seed) * (z.type === 'runner' ? 0.14 : 0.34);
      target += wobble;
      z.angle += angleDiff(target, z.angle) * Math.min(1, dt * (z.type === 'runner' ? 7 : 3.8));

      const minD = z.radius + p.radius + 2;
      if (d > minD + 1 && !p.dead && state.mode !== 'menu') {
        let sp = z.speed * z.slow;
        if (z.type === 'runner') sp *= 0.9 + Math.sin(state.time * 6 + z.seed) * 0.15;
        z.x += Math.cos(z.angle) * sp * dt;
        z.y += Math.sin(z.angle) * sp * dt;
      } else if (state.mode === 'menu') {
        z.x += Math.cos(z.angle + Math.PI / 2) * z.speed * 0.25 * dt;
        z.y += Math.sin(z.angle + Math.PI / 2) * z.speed * 0.25 * dt;
      }

      // attack
      if (state.mode === 'playing' && !p.dead) {
        z.attackCd -= dt;
        if (d < minD + 7 && z.attackCd <= 0) {
          z.attackCd = z.type === 'runner' ? 0.95 : z.type === 'brute' ? 1.55 : 1.35;
          z.swipe = 0.32;
          if (p.invuln <= 0) {
            damagePlayer(z.damage, Math.atan2(p.y - z.y, p.x - z.x), z);
          }
        }
      }

      // crowd separation
      for (const o of list) {
        if (o === z || o.dead) continue;
        const ox = z.x - o.x, oy = z.y - o.y;
        const od = Math.hypot(ox, oy);
        const min = z.radius + o.radius - 1;
        if (od < min && od > 0.001) {
          const push = (min - od) / od * 0.5;
          z.x += ox * push;
          z.y += oy * push;
        }
      }

      CR.resolveProps(z);
    }
  }

  function damagePlayer(dmg, dir, source) {
    const p = player;
    if (p.dead || p.invuln > 0) return;
    p.hp -= dmg;
    p.invuln = 0.9;
    p.hurtFlash = 1;
    p.vx += Math.cos(dir) * 120;
    p.vy += Math.sin(dir) * 120;
    state.shake = Math.max(state.shake, 6);
    state.damageFlash = 1;
    state.flash = Math.max(state.flash, 0.35);
    CR.dom.damage.classList.add('hit');
    setTimeout(() => CR.dom.damage.classList.remove('hit'), 110);
    spawnBlood(p.x, p.y, dir, 14, 1.0);
    CR.addSplat(p.x, p.y, dir, 8, 0.6, 0.6);
    for (let i = 0; i < 7; i++) {
      CR.screenDrops.push({
        x: rand(0, view.w), y: rand(-4, view.h * 0.2),
        vx: rand(-8, 8), vy: rand(10, 40), r: rand(1, 3), life: rand(0.8, 2.2), max: 2.2
      });
    }
    if (CR.sound) CR.sound.hurt();
    if (source) {
      source.vx -= Math.cos(dir) * 30;
      source.vy -= Math.sin(dir) * 30;
    }
    if (p.hp <= 0) {
      p.hp = 0;
      die();
    }
  }

  function die() {
    const p = player;
    p.dead = true;
    state.mode = 'dead';
    state.slowmo = 1.3;
    state.shake = 13;
    state.flash = 1;
    state.whiteFlash = 0.7;
    spawnBlood(p.x, p.y, p.aim, 60, 1.8);
    CR.addPool(p.x, p.y, 26, 0.9);
    CR.corpses.push({ x: p.x, y: p.y, angle: p.aim, scale: 1, kind: 'player', life: 999, max: 999, static: true });
    CR.dom.frenzy.classList.remove('on');
    CR.dom.damage.classList.remove('low');
    document.body.classList.add('menu-open');
    if (CR.sound) {
      CR.sound.death();
      CR.sound.saw(0, false);
    }
    setTimeout(() => {
      if (state.mode !== 'dead') return;
      CR.dom.statWave.textContent = state.wave;
      CR.dom.statKills.textContent = state.kills;
      CR.dom.statScore.textContent = state.score.toLocaleString('en-US');
      CR.dom.statCombo.textContent = 'x' + state.bestCombo;
      CR.dom.gameover.classList.remove('hidden');
    }, 1200);
  }

  // ------------------------------------------------------------
  //  pickups / particles / corpses
  // ------------------------------------------------------------
  function updatePickups(dt) {
    const p = player;
    for (const item of CR.pickups) {
      item.life -= dt;
      item.bob += dt * 3;
      if (dist(p.x, p.y, item.x, item.y) < 16 && !p.dead) {
        item.life = 0;
        if (item.type === 'medkit') {
          p.hp = Math.min(p.maxHp, p.hp + 28);
          CR.addFloater('+28 HP', p.x, p.y - 26, '#d7ff4a', 1);
        } else {
          p.frenzy = Math.min(100, p.frenzy + 55);
          CR.addFloater('+55 FRENZY', p.x, p.y - 26, '#ffb15c', 1);
        }
        if (CR.sound) CR.sound.pickup();
      }
    }
    CR.pickups = CR.pickups.filter(item => item.life > 0);
  }

  function updateParticles(dt) {
    // blood / dust / sparks
    for (const pt of CR.particles) {
      pt.life -= dt;
      if (pt.z > 0 || pt.type === 'blood' || pt.type === 'dirt') {
        pt.x += pt.vx * dt;
        pt.y += pt.vy * dt;
        pt.z += pt.vz * dt;
        pt.vz -= (pt.type === 'spark' ? 320 : 240) * dt;
        if (pt.z <= 0) {
          if (pt.type === 'blood') {
            CR.addSplat(pt.x, pt.y, Math.atan2(pt.vy, pt.vx), 2, 0.22, 0.65);
            pt.life = 0;
          } else {
            pt.z = 0;
            pt.vz *= -0.2;
            if (Math.abs(pt.vz) < 8) pt.vz = 0;
            pt.vx *= 0.7; pt.vy *= 0.7;
          }
        }
      } else {
        pt.x += pt.vx * dt;
        pt.y += pt.vy * dt;
      }
    }
    CR.particles = CR.particles.filter(pt => pt.life > 0);
    if (CR.particles.length > 900) CR.particles.splice(0, CR.particles.length - 900);

    // gibs
    for (const g of CR.gibs) {
      g.life -= dt;
      if (!g.grounded) {
        g.x += g.vx * dt;
        g.y += g.vy * dt;
        g.z += g.vz * dt;
        g.vz -= 320 * dt;
        g.rot += g.vr * dt;
        if (g.z <= 0) {
          g.z = 0;
          if (g.vz < -45) {
            g.vz *= -0.28;
            g.vx *= 0.55; g.vy *= 0.55; g.vr *= 0.5;
            CR.addSplat(g.x, g.y, rand(0, TAU), 3, 0.3, 0.6);
          } else {
            g.grounded = true;
            g.vx = 0; g.vy = 0; g.vz = 0; g.vr = 0;
            CR.addSplat(g.x, g.y, g.rot, 4, 0.35, 0.65);
            if (g.type === 'head') CR.addPool(g.x, g.y, 5, 0.6);
          }
        }
      }
    }
    CR.gibs = CR.gibs.filter(g => g.life > 0);
    if (CR.gibs.length > 260) CR.gibs.splice(0, CR.gibs.length - 260);

    // floating text
    for (const f of CR.floaters) {
      f.life -= dt;
      f.y -= 18 * dt;
      f.x += Math.sin((f.max - f.life) * 4 + f.seed) * 5 * dt;
    }
    CR.floaters = CR.floaters.filter(f => f.life > 0);

    // afterimages
    for (const a of CR.afterimages) a.life -= dt;
    CR.afterimages = CR.afterimages.filter(a => a.life > 0);

    // screen blood
    for (const d of CR.screenDrops) {
      d.life -= dt;
      d.x += d.vx * dt;
      d.y += d.vy * dt;
      d.vy += 12 * dt;
    }
    CR.screenDrops = CR.screenDrops.filter(d => d.life > 0);

    // corpses fade
    for (const c of CR.corpses) {
      if (!c.static) c.life -= dt;
    }
    CR.corpses = CR.corpses.filter(c => c.life > 0);
    if (CR.corpses.length > 80) CR.corpses.splice(0, CR.corpses.length - 80);
  }

  function updateWaves(dt) {
    if (state.mode !== 'playing') return;
    if (state.waveState === 'active') {
      state.spawnTimer -= dt;
      if (state.spawnQueue.length && state.spawnTimer <= 0) {
        state.spawnTimer = Math.max(0.14, 0.42 - state.wave * 0.012);
        const type = state.spawnQueue.shift();
        CR.spawnZombie(type, false);
      }
      state.remaining = state.spawnQueue.length + CR.zombies.filter(z => !z.dead).length;
      if (!state.spawnQueue.length && CR.zombies.length === 0) {
        state.waveState = 'clear';
        state.waveTimer = 4.2;
        CR.announce('YARD CLEARED', 'CATCH YOUR BREATH // NEXT WAVE INCOMING', 3.4);
        player.hp = Math.min(player.maxHp, player.hp + 8);
        player.frenzy = Math.min(100, player.frenzy + 8);
        if (CR.sound) CR.sound.wave();
      }
    } else if (state.waveState === 'clear') {
      state.waveTimer -= dt;
      if (state.waveTimer <= 0) CR.startWave(state.wave + 1);
    }
  }

  function updateCamera(dt) {
    const p = player;
    const lookX = Math.cos(p.aim) * 16;
    const lookY = Math.sin(p.aim) * 16;
    let tx = p.x + lookX - view.w / 2;
    let ty = p.y + lookY - view.h / 2;
    if (state.mode === 'menu') {
      tx = 800 - view.w / 2 + Math.sin(state.time * 0.1) * 26;
      ty = 500 - view.h / 2 + Math.cos(state.time * 0.08) * 14;
    }
    tx = clamp(tx, 0, Math.max(0, world.w - view.w));
    ty = clamp(ty, 0, Math.max(0, world.h - view.h));
    const smooth = state.mode === 'menu' ? 2.5 : 9;
    cam.x = lerp(cam.x, tx, Math.min(1, dt * smooth));
    cam.y = lerp(cam.y, ty, Math.min(1, dt * smooth));
  }

  CR.update = function (rawDt) {
    let dt = Math.min(rawDt, 0.05);
    state.time += dt;
    if (state.hitstop > 0) {
      state.hitstop -= dt;
      dt *= 0.18;
    }
    if (state.slowmo > 0) {
      state.slowmo -= rawDt;
      dt *= 0.35;
    }
    state.shake = Math.max(0, state.shake - rawDt * 18);
    state.flash = Math.max(0, state.flash - rawDt * 3.4);
    state.whiteFlash = Math.max(0, state.whiteFlash - rawDt * 3.2);
    state.damageFlash = Math.max(0, state.damageFlash - rawDt * 3.0);
    if (state.announce) {
      state.announce.time -= rawDt;
      if (state.announce.time <= 0) state.announce = null;
    }
    if (state.comboTimer > 0) {
      state.comboTimer -= rawDt;
      if (state.comboTimer <= 0) state.combo = 0;
    }
    if (state.lowHealth !== (player.hp <= 30 && player.hp > 0)) {
      state.lowHealth = player.hp <= 30 && player.hp > 0;
      CR.dom.damage.classList.toggle('low', state.lowHealth);
    }

    if (state.mode !== 'paused') {
      state.gameTime += dt;
      updatePlayer(dt);
      if (state.mode === 'playing') {
        updateZombies(dt);
        updateWaves(dt);
        updatePickups(dt);
      } else if (state.mode === 'menu') {
        updateMenuZombies(dt);
      } else if (state.mode === 'dead') {
        updateZombies(dt);
      }
      updateParticles(dt);
      updateCamera(dt);
      CR.updateFog(dt);
      updateRain(dt);
    }

    state.shakeX = state.shake ? rand(-state.shake, state.shake) : 0;
    state.shakeY = state.shake ? rand(-state.shake, state.shake) : 0;

    // lightning
    state.lightning -= rawDt;
    if (state.lightning <= 0) {
      state.lightning = rand(7, 19);
      state.whiteFlash = 0.65;
      if (CR.sound) {
        CR.sound.thunder();
        setTimeout(() => CR.sound.thunder(), 420);
      }
    }
    input.pressed.clear();
  };

  function updateMenuZombies(dt) {
    // The title screen is a living diorama: distant ghouls shuffle through the mist.
    for (const z of CR.zombies) {
      z.phase += dt * 1.7;
      z.x += Math.cos(z.angle + Math.PI / 2) * z.speed * 0.2 * dt;
      z.y += Math.sin(z.angle + Math.PI / 2) * z.speed * 0.2 * dt;
      z.angle += Math.sin(state.time + z.seed) * 0.002;
      if (z.x < 120 || z.x > world.w - 120) z.angle += Math.PI;
      if (z.y < 120 || z.y > world.h - 120) z.angle += Math.PI;
    }
  }

  function updateRain(dt) {
    for (const r of CR.rain) {
      r.y += r.speed * dt;
      r.x -= r.speed * 0.16 * dt;
      if (r.y > view.h + 8) {
        r.y = rand(-20, -2);
        r.x = rand(0, view.w + 30);
      }
      if (r.x < -8) r.x = view.w + 8;
    }
  }

  CR.addFloater = function (text, x, y, color = '#e9e2cf', scale = 1) {
    CR.floaters.push({ text, x, y, color, scale, life: 1.1, max: 1.1, seed: rand(0, 10) });
  };

  CR.spawnMenu = function () {
    CR.zombies.length = 0;
    CR.particles.length = 0;
    CR.corpses.length = 0;
    CR.gibs.length = 0;
    CR.floaters.length = 0;
    CR.pickups.length = 0;
    CR.screenDrops.length = 0;
    const p = player;
    p.x = 800; p.y = 520; p.hp = 100; p.dead = false; p.rev = 0.12;
    p.aim = -0.35; p.walkPhase = 0;
    cam.x = clamp(p.x - view.w / 2, 0, world.w - view.w);
    cam.y = clamp(p.y - view.h / 2, 0, world.h - view.h);
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU + rand(-0.4, 0.4);
      const d = rand(150, 260);
      const z = CR.spawnZombie(i % 3 === 0 ? 'runner' : 'walker', false);
      z.x = clamp(p.x + Math.cos(a) * d, 60, world.w - 60);
      z.y = clamp(p.y + Math.sin(a) * d, 60, world.h - 60);
      z.angle = a + Math.PI;
      z.attackCd = 99;
    }
    state.mode = 'menu';
  };
})();

(() => {
  'use strict';
  const CR = window.CR;
  const {
    TAU, clamp, lerp, rand, pick, dist, angleDiff, drawText, textWidth,
    ctx, view, world, cam, state, player, input
  } = CR;

  const lightCanvas = document.createElement('canvas');
  const lightCtx = lightCanvas.getContext('2d');
  lightCanvas.width = view.w;
  lightCanvas.height = view.h;

  CR.onResize = function () {
    lightCanvas.width = view.w;
    lightCanvas.height = view.h;
    CR.buildRain();
  };

  // ------------------------------------------------------------
  //  small helpers
  // ------------------------------------------------------------
  function shadow(x, y, rx, ry, a = 0.38) {
    ctx.globalAlpha = a;
    ctx.fillStyle = '#040605';
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  function visible(x, y, margin = 90) {
    return x > cam.x - margin && x < cam.x + view.w + margin &&
      y > cam.y - margin && y < cam.y + view.h + margin;
  }

  function panel(x, y, w, h, a = 0.52) {
    ctx.fillStyle = `rgba(5,8,9,${a})`;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = 'rgba(233,226,207,0.08)';
    ctx.fillRect(x, y, w, 1);
  }

  function bar(x, y, w, h, pct, color, bg = '#1b1d1a') {
    ctx.fillStyle = '#050706';
    ctx.fillRect(x - 1, y - 1, w + 2, h + 2);
    ctx.fillStyle = bg;
    ctx.fillRect(x, y, w, h);
    const fw = Math.round(w * clamp(pct, 0, 1));
    ctx.fillStyle = color;
    ctx.fillRect(x, y, fw, h);
    ctx.fillStyle = 'rgba(255,255,255,0.22)';
    ctx.fillRect(x, y, fw, 1);
  }

  // ------------------------------------------------------------
  //  props
  // ------------------------------------------------------------
  function drawProp(p, t) {
    const spr = p.sprite;
    if (!spr) return;
    const sw = spr.width, sh = spr.height;
    const ox = Math.round(p.x - sw / 2);
    let oy;
    if (p.oy === 1) oy = Math.round(p.y - sh + 4);
    else if (p.oy === 0.5) oy = Math.round(p.y - sh / 2);
    else oy = Math.round(p.y - sh);

    if (p.type === 'pine' || p.type === 'deadTree') {
      shadow(p.x + 10, p.y + 3, 26, 8, 0.32);
    } else if (p.type === 'truck') {
      shadow(p.x + 3, p.y + 10, 61, 15, 0.38);
    } else if (p.type === 'dumpster') {
      shadow(p.x + 2, p.y + 8, 43, 12, 0.38);
    } else if (p.type === 'lamp') {
      shadow(p.x + 2, p.y + 2, 9, 3, 0.34);
    } else if (p.type === 'meatframe') {
      shadow(p.x + 3, p.y + 1, 22, 6, 0.3);
    } else {
      shadow(p.x + 2, p.y + 4, sw * 0.3, sh * 0.14, 0.3);
    }

    ctx.drawImage(spr, ox, oy);

    if (p.type === 'firebarrel') drawFireBarrel(p, t);
    if (p.type === 'lamp') drawLampGlow(p, t);
    if (p.type === 'truck') {
      // weak headlight bloom, kept subtle
      ctx.globalAlpha = 0.16;
      ctx.fillStyle = '#e7cf86';
      ctx.fillRect(p.x + 62, p.y - 8, 6, 2);
      ctx.fillRect(p.x + 62, p.y + 5, 6, 2);
      ctx.globalAlpha = 1;
    }
  }

  function drawFireBarrel(p, t) {
    const x = Math.round(p.x), y = Math.round(p.y - 20);
    const flick = Math.sin(t * 13 + p.x) * 0.5 + 0.5;
    for (let i = 0; i < 5; i++) {
      const h = 4 + Math.sin(t * (9 + i) + i * 2.1) * 3 + flick * 3;
      const ox = Math.sin(t * 7 + i * 1.7) * 3;
      ctx.globalAlpha = 0.85 - i * 0.12;
      ctx.fillStyle = i < 2 ? '#ffd166' : i < 4 ? '#ff8a2b' : '#c33b17';
      ctx.fillRect(x - 4 + i * 2 + ox, y - h, 2, h + 2);
    }
    ctx.globalAlpha = 0.35 + flick * 0.25;
    ctx.fillStyle = '#ffb347';
    ctx.fillRect(x - 5, y - 2, 10, 2);
    ctx.globalAlpha = 1;
    // embers
    for (let i = 0; i < 3; i++) {
      const yy = (t * (12 + i * 5) + i * 31) % 38;
      ctx.globalAlpha = (1 - yy / 38) * 0.7;
      ctx.fillStyle = i % 2 ? '#ffd166' : '#ff6b1a';
      ctx.fillRect(x + Math.sin(t * 2 + i * 4) * 7, y - yy, 1, 1);
    }
    ctx.globalAlpha = 1;
  }

  function drawLampGlow(p, t) {
    const x = p.x - 8, y = p.y - 76;
    const flick = 0.86 + Math.sin(t * 17 + p.x) * 0.04 + Math.sin(t * 2.7) * 0.03;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(x, y, 1, x, y, 26);
    g.addColorStop(0, `rgba(255,224,157,${0.36 * flick})`);
    g.addColorStop(0.4, `rgba(255,186,94,${0.12 * flick})`);
    g.addColorStop(1, 'rgba(255,170,70,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 30, y - 30, 60, 60);
    ctx.restore();
  }

  // ------------------------------------------------------------
  //  player
  // ------------------------------------------------------------
  function drawPlayer(p, t) {
    if (p.dead) {
      drawPlayerCorpse(p);
      return;
    }
    const px = Math.round(p.x), py = Math.round(p.y);
    shadow(px + 1, py + 4, 13, 5, 0.5);

    // frenzy aura
    if (p.frenzyTime > 0) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const g = ctx.createRadialGradient(px, py, 3, px, py, 30);
      g.addColorStop(0, 'rgba(255,40,40,0.16)');
      g.addColorStop(0.55, 'rgba(190,10,20,0.09)');
      g.addColorStop(1, 'rgba(120,0,10,0)');
      ctx.fillStyle = g;
      ctx.fillRect(px - 32, py - 32, 64, 64);
      ctx.restore();
    }

    // attack arc, world-space
    if (p.attack && p.rev > 0.2) {
      const frenzy = p.frenzyTime > 0;
      const range = 30 + p.rev * 5 + (frenzy ? 7 : 0);
      const sweep = 0.9 + (frenzy ? 0.22 : 0);
      const pulse = 0.18 + Math.abs(Math.sin(t * 24)) * 0.18;
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(p.aim);
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = `rgba(255,138,43,${pulse})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, range, -sweep, sweep);
      ctx.stroke();
      ctx.strokeStyle = `rgba(255,232,168,${pulse * 0.65})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(0, 0, range - 3, -sweep * 0.8, sweep * 0.8);
      ctx.stroke();
      // slash flick
      const a = -sweep + ((t * 7) % 1) * sweep * 2;
      ctx.fillStyle = `rgba(255,210,120,${0.2 + pulse})`;
      ctx.fillRect(Math.cos(a) * (range - 1), Math.sin(a) * (range - 1) - 1, 3, 2);
      ctx.restore();
    }

    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(p.aim);
    const walking = p.moving || p.dashTime > 0;
    const walk = walking ? Math.sin(p.walkPhase) : Math.sin(t * 2) * 0.2;
    const bob = walking ? Math.abs(Math.sin(p.walkPhase)) * 0.9 : Math.sin(t * 2) * 0.35;
    ctx.translate(0, -bob);

    // trailing legs
    drawBoot(-7 + walk * 2.4, -4, '#161b17', '#2a342c');
    drawBoot(-7 - walk * 2.4, 4, '#121713', '#232d26');

    // backpack
    ctx.fillStyle = '#0b100e';
    rr(ctx, -11, -5, 6, 10, 2); ctx.fill();
    ctx.fillStyle = '#393326';
    rr(ctx, -10, -4, 4, 8, 1); ctx.fill();
    ctx.fillStyle = '#17130e';
    ctx.fillRect(-10, -2, 4, 1);
    ctx.fillRect(-10, 2, 4, 1);

    // torso outline and jacket
    ctx.fillStyle = '#0a0f0d';
    rr(ctx, -8, -7, 14, 14, 4); ctx.fill();
    ctx.fillStyle = '#243c35';
    rr(ctx, -7, -6, 12, 12, 3); ctx.fill();
    ctx.fillStyle = '#355449';
    ctx.fillRect(-6, -6, 7, 1);
    ctx.fillRect(-6, -5, 3, 1);
    ctx.fillStyle = '#1a2c27';
    ctx.fillRect(-5, 4, 8, 2);
    // belt
    ctx.fillStyle = '#151712';
    ctx.fillRect(-3, -7, 2, 14);
    ctx.fillStyle = '#a58c4d';
    ctx.fillRect(-3, -1, 2, 2);
    // blood on jacket
    ctx.globalAlpha = 0.55;
    ctx.fillStyle = '#6c0710';
    ctx.fillRect(-4, 2, 4, 2);
    ctx.fillRect(2, -5, 2, 3);
    ctx.globalAlpha = 1;

    // shoulder pads
    ctx.fillStyle = '#0d1512';
    rr(ctx, -3, -8, 6, 3, 1); ctx.fill();
    rr(ctx, -3, 5, 6, 3, 1); ctx.fill();
    ctx.fillStyle = '#3b564a';
    ctx.fillRect(-2, -8, 4, 1);
    ctx.fillRect(-2, 7, 4, 1);

    // arms
    const armBend = p.attack ? 1 : 0;
    ctx.strokeStyle = '#1b2d28';
    ctx.lineWidth = 4;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(2, -5);
    ctx.lineTo(8 + armBend, -2.5);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(2, 5);
    ctx.lineTo(8 + armBend, 2.5);
    ctx.stroke();
    ctx.strokeStyle = '#4a6658';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(2, -6); ctx.lineTo(8, -3); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(2, 4); ctx.lineTo(8, 1); ctx.stroke();
    // hands
    ctx.fillStyle = '#5f4b36';
    ctx.fillRect(8 + armBend, -4, 3, 3);
    ctx.fillRect(8 + armBend, 1, 3, 3);

    // chainsaw
    drawChainsaw(p, t, armBend);

    // head / gas mask
    ctx.fillStyle = '#0b110e';
    ctx.beginPath(); ctx.arc(4, 0, 5.5, 0, TAU); ctx.fill();
    ctx.fillStyle = '#1c2b24';
    ctx.beginPath(); ctx.arc(4, 0, 4.6, 0, TAU); ctx.fill();
    ctx.fillStyle = '#576553';
    ctx.beginPath(); ctx.arc(5.4, 0, 3.8, 0, TAU); ctx.fill();
    // lenses
    ctx.fillStyle = '#0a0d0a';
    ctx.fillRect(6, -2, 3, 2);
    ctx.fillRect(6, 1, 3, 2);
    ctx.fillStyle = '#d6e58c';
    ctx.fillRect(7, -2, 1, 1);
    ctx.fillRect(7, 2, 1, 1);
    // filter
    ctx.fillStyle = '#2d372f';
    ctx.fillRect(8, -1, 3, 2);
    ctx.fillStyle = '#0b100d';
    ctx.fillRect(9, -1, 1, 2);
    // hood highlights
    ctx.fillStyle = '#31443a';
    ctx.fillRect(1, -4, 2, 1);
    ctx.fillRect(1, 3, 2, 1);

    // hit flash
    if (p.hurtFlash > 0) {
      ctx.globalAlpha = p.hurtFlash * 0.4;
      ctx.fillStyle = '#ff202b';
      ctx.beginPath(); ctx.arc(0, 0, 14, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
    }

    // dash afterimage streaks
    if (p.dashTime > 0) {
      ctx.globalAlpha = 0.4;
      ctx.strokeStyle = '#b8d2c2';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath();
        ctx.moveTo(-14 - i * 5, -4 + i * 4);
        ctx.lineTo(-25 - i * 5, -4 + i * 4);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    ctx.restore();
  }

  function drawBoot(x, y, c1, c2) {
    ctx.fillStyle = c1;
    rr(ctx, x - 3, y - 2, 7, 4, 1); ctx.fill();
    ctx.fillStyle = c2;
    ctx.fillRect(x - 2, y - 2, 4, 1);
    ctx.fillStyle = '#070908';
    ctx.fillRect(x + 2, y + 1, 2, 1);
  }

  function drawChainsaw(p, t, armBend) {
    const sx = 9 + armBend + p.swing * 1.2;
    const rev = p.rev;
    const phase = p.bladePhase;

    // glow / heat
    if (rev > 0.15) {
      ctx.globalAlpha = 0.12 + rev * 0.13;
      ctx.fillStyle = p.frenzyTime > 0 ? '#ff3038' : '#ff8a2b';
      ctx.fillRect(sx - 2, -6, 8, 12);
      ctx.globalAlpha = 1;
    }

    // rear handle
    ctx.fillStyle = '#0b0d0b';
    rr(ctx, sx - 2, -7, 6, 3, 1); ctx.fill();
    ctx.fillRect(sx - 1, -5, 2, 2);

    // engine body
    ctx.fillStyle = '#1a0c08';
    rr(ctx, sx, -4, 7, 8, 1); ctx.fill();
    ctx.fillStyle = '#8d2d12';
    rr(ctx, sx + 1, -3, 5, 6, 1); ctx.fill();
    ctx.fillStyle = '#d85e1c';
    ctx.fillRect(sx + 1, -3, 5, 2);
    ctx.fillStyle = '#f08a35';
    ctx.fillRect(sx + 2, -3, 2, 1);
    ctx.fillStyle = '#3a140c';
    ctx.fillRect(sx + 2, 1, 3, 2);
    // pull start
    ctx.fillStyle = '#15110c';
    ctx.fillRect(sx + 1, 4, 3, 2);
    // tiny brand slash
    ctx.fillStyle = '#ffcf7a';
    ctx.fillRect(sx + 4, 0, 1, 2);

    // blade
    const bx = sx + 7;
    const blen = 18;
    ctx.fillStyle = '#151817';
    ctx.fillRect(bx, -2, blen, 4);
    ctx.fillStyle = '#858c86';
    ctx.fillRect(bx, -1.5, blen, 3);
    ctx.fillStyle = '#b9c0b7';
    ctx.fillRect(bx, -1, blen - 2, 1);
    ctx.fillStyle = '#3d433f';
    ctx.fillRect(bx, 1, blen, 1);

    // chain teeth
    const off = Math.floor(phase) % 4;
    ctx.fillStyle = '#dce0d2';
    for (let i = 0; i < blen; i += 2) {
      if ((i + off) % 4 === 0) {
        ctx.fillRect(bx + i, -3, 1, 1);
        ctx.fillRect(bx + i + 1, 2, 1, 1);
      }
    }
    // cutting glint
    if (rev > 0.5) {
      ctx.globalAlpha = 0.3 + Math.sin(t * 30) * 0.2;
      ctx.fillStyle = '#fff2c4';
      ctx.fillRect(bx + 1, -2, blen - 4, 1);
      ctx.globalAlpha = 1;
    }

    // guard
    ctx.fillStyle = '#242822';
    ctx.fillRect(bx - 1, -4, 2, 8);
    ctx.fillStyle = '#5a6159';
    ctx.fillRect(bx - 1, -4, 1, 8);

    // motion streaks
    if (rev > 0.3) {
      ctx.globalAlpha = 0.18 + rev * 0.14;
      ctx.fillStyle = '#ffd166';
      ctx.fillRect(bx + 2, -5, blen - 3, 1);
      ctx.fillRect(bx + 1, 4, blen - 2, 1);
      ctx.globalAlpha = 1;
    }
  }

  function drawPlayerCorpse(p) {
    ctx.save();
    ctx.translate(Math.round(p.x), Math.round(p.y));
    ctx.rotate(p.aim);
    shadow(0, 4, 13, 5, 0.4);
    ctx.fillStyle = '#1a2b26';
    rr(ctx, -9, -5, 15, 10, 3); ctx.fill();
    ctx.fillStyle = '#0d1411';
    rr(ctx, -12, -3, 6, 7, 2); ctx.fill();
    ctx.fillStyle = '#4e5d4d';
    ctx.beginPath(); ctx.arc(5, 0, 4, 0, TAU); ctx.fill();
    ctx.fillStyle = '#0b100d';
    ctx.fillRect(5, -2, 3, 2);
    ctx.fillStyle = '#6b0710';
    ctx.globalAlpha = 0.6;
    ctx.fillRect(-6, -2, 9, 4);
    ctx.restore();
  }

  // ------------------------------------------------------------
  //  zombies
  // ------------------------------------------------------------
  function drawZombie(z, t) {
    const px = Math.round(z.x), py = Math.round(z.y);
    const s = z.scale;
    shadow(px + 1, py + 3, 9 * s, 4 * s, 0.42);

    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(z.angle);
    const walk = Math.sin(t * (z.type === 'runner' ? 11 : 5.5) + z.seed);
    const bob = Math.abs(walk) * 0.7;
    ctx.translate(0, -bob);
    ctx.scale(s, s);

    const skin = z.boss ? '#7a7654' : z.type === 'runner' ? '#798264' : '#6d7c5b';
    const skinDark = z.boss ? '#4f4b35' : '#4d5b42';
    const shirt = z.type === 'runner' ? '#3c2c2a' : z.boss ? '#2d2520' : '#33412e';
    const shirtDark = z.type === 'runner' ? '#241b1a' : z.boss ? '#1c1714' : '#202b1e';

    // legs
    drawZLeg(-5 + walk * 2.2, -3, skinDark, skin);
    drawZLeg(-5 - walk * 2.2, 3, skinDark, skin);
    if (z.boss) {
      // heavy feet
      ctx.fillStyle = '#17140f';
      ctx.fillRect(-9, -6, 5, 3);
      ctx.fillRect(-9, 3, 5, 3);
    }

    // torso
    ctx.fillStyle = '#0c100c';
    rr(ctx, -7, -6, 13, 12, 3); ctx.fill();
    ctx.fillStyle = shirt;
    rr(ctx, -6, -5, 11, 10, 2); ctx.fill();
    ctx.fillStyle = shirtDark;
    ctx.fillRect(-5, 2, 9, 2);
    // exposed chest / ribs
    ctx.fillStyle = skinDark;
    rr(ctx, 0, -3, 4, 5, 1); ctx.fill();
    ctx.fillStyle = '#a49b7d';
    for (let i = 0; i < 3; i++) ctx.fillRect(1, -2 + i * 2, 3, 1);
    // blood
    ctx.globalAlpha = 0.6;
    ctx.fillStyle = '#690710';
    ctx.fillRect(-4, -4, 3, 2);
    ctx.fillRect(-1, 2, 4, 1);
    ctx.globalAlpha = 1;

    // arms
    if (z.limbs.armL) {
      drawZArm(1, -5, walk, skin, skinDark, false);
    } else {
      drawStump(1, -5, skinDark);
    }
    if (z.limbs.armR) {
      drawZArm(1, 5, -walk, skin, skinDark, true);
    } else {
      drawStump(1, 5, skinDark);
    }

    // neck + head
    if (z.limbs.head) {
      ctx.fillStyle = '#11150f';
      ctx.beginPath(); ctx.arc(5, 0, 5.2, 0, TAU); ctx.fill();
      ctx.fillStyle = skin;
      ctx.beginPath(); ctx.arc(5.2, 0, 4.4, 0, TAU); ctx.fill();
      ctx.fillStyle = skinDark;
      ctx.fillRect(3, -4, 3, 2);
      // hair / scalp
      ctx.fillStyle = z.boss ? '#17130e' : '#23251b';
      ctx.fillRect(2, -4, 4, 3);
      ctx.fillRect(1, -2, 2, 2);
      // jaw / mouth
      ctx.fillStyle = '#24120f';
      ctx.fillRect(7, 1, 3, 2);
      ctx.fillStyle = '#b9ae8d';
      ctx.fillRect(8, 1, 1, 1);
      // eyes
      const eye = z.type === 'runner' ? '#ff3b43' : z.boss ? '#ff9a2b' : '#d6cf74';
      ctx.fillStyle = eye;
      ctx.fillRect(6, -2, 2, 1);
      ctx.fillRect(6, 2, 2, 1);
      ctx.fillStyle = 'rgba(255,80,60,0.35)';
      ctx.fillRect(6, -2, 3, 1);
      // wounds
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = '#5b070d';
      ctx.fillRect(4, 3, 2, 2);
      ctx.globalAlpha = 1;
      if (z.type === 'brute' || z.boss) {
        // bone spikes / butcher apron
        ctx.fillStyle = '#d1c5a1';
        ctx.fillRect(-1, -7, 2, 2);
        ctx.fillRect(-3, 5, 2, 2);
        if (z.boss) {
          ctx.fillStyle = '#7a0b12';
          rr(ctx, -4, -4, 6, 8, 1); ctx.fill();
          ctx.fillStyle = '#c8b896';
          ctx.fillRect(-2, 0, 1, 5);
        }
      }
    } else {
      // neck stump
      ctx.fillStyle = skinDark;
      ctx.fillRect(3, -2, 4, 4);
      ctx.fillStyle = '#7d0a12';
      ctx.fillRect(5, -1, 2, 2);
    }

    // attack swipe
    if (z.swipe > 0) {
      ctx.globalAlpha = z.swipe * 2.2;
      ctx.strokeStyle = '#ff4d55';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, 16, -0.7, 0.7);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // flash
    if (z.flash > 0) {
      ctx.globalAlpha = z.flash * 2.0;
      ctx.fillStyle = '#ff4b52';
      ctx.beginPath(); ctx.arc(1, 0, 9, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    // health bar
    if (!z.boss && z.hp < z.maxHp) {
      const w = Math.max(12, 16 * s);
      const x = px - w / 2, y = py - 14 * s - 5;
      ctx.fillStyle = '#050706';
      ctx.fillRect(x - 1, y - 1, w + 2, 3);
      ctx.fillStyle = '#391017';
      ctx.fillRect(x, y, w, 1);
      ctx.fillStyle = '#b91622';
      ctx.fillRect(x, y, w * clamp(z.hp / z.maxHp, 0, 1), 1);
    }
    if (z.boss) {
      // marker
      ctx.globalAlpha = 0.6;
      ctx.fillStyle = '#ffb15c';
      ctx.fillRect(px - 1, py - 46, 2, 2);
      ctx.globalAlpha = 1;
    }
  }

  function drawZLeg(x, y, c1, c2) {
    ctx.fillStyle = c1;
    rr(ctx, x - 3, y - 2, 8, 4, 1); ctx.fill();
    ctx.fillStyle = c2;
    ctx.fillRect(x - 1, y - 1, 4, 1);
  }

  function drawZArm(x, y, swing, skin, dark, right) {
    const ex = x + 9 + Math.sin(swing) * 1.5;
    const ey = y + (right ? 2.4 : -2.4) + Math.cos(swing) * 1.2;
    ctx.strokeStyle = dark;
    ctx.lineWidth = 3.6;
    ctx.lineCap = 'butt';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(ex, ey);
    ctx.stroke();
    ctx.strokeStyle = skin;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(x, y - 0.5);
    ctx.lineTo(ex, ey - 0.5);
    ctx.stroke();
    // claw hand
    ctx.fillStyle = dark;
    ctx.fillRect(ex - 1, ey - 1.5, 3, 3);
    ctx.fillStyle = '#b7ad8b';
    ctx.fillRect(ex + 2, ey - 2, 1, 1);
    ctx.fillRect(ex + 2, ey + 1, 1, 1);
    ctx.fillRect(ex + 3, ey, 1, 1);
  }

  function drawStump(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y - 1, 3, 3);
    ctx.fillStyle = '#7d0a12';
    ctx.fillRect(x + 2, y - 1, 1, 3);
  }

  // ------------------------------------------------------------
  //  corpses, pickups, gibs, particles
  // ------------------------------------------------------------
  function drawCorpse(c) {
    const alpha = c.static ? 1 : clamp(c.life / 5, 0, 1);
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(Math.round(c.x), Math.round(c.y));
    ctx.rotate(c.angle);
    const s = c.scale || 1;
    ctx.scale(s, s);
    if (c.kind === 'player') {
      ctx.fillStyle = '#243c35';
      rr(ctx, -10, -5, 16, 10, 3); ctx.fill();
      ctx.fillStyle = '#0b100e';
      rr(ctx, -13, -3, 5, 6, 2); ctx.fill();
      ctx.fillStyle = '#4e5d4d';
      ctx.beginPath(); ctx.arc(5, 0, 4, 0, TAU); ctx.fill();
      ctx.fillStyle = '#0b100d';
      ctx.fillRect(5, -2, 3, 2);
      ctx.fillStyle = '#6b0710';
      ctx.globalAlpha = alpha * 0.55;
      ctx.fillRect(-7, -2, 12, 4);
    } else if (c.kind === 'crawler') {
      ctx.fillStyle = '#2a3426';
      rr(ctx, -8, -4, 11, 8, 3); ctx.fill();
      ctx.fillStyle = '#6d7c5b';
      ctx.beginPath(); ctx.arc(4, 0, 3.8, 0, TAU); ctx.fill();
      ctx.fillStyle = '#171a12';
      ctx.fillRect(3, -3, 3, 2);
      ctx.fillStyle = '#5d0710';
      ctx.globalAlpha = alpha * 0.6;
      ctx.fillRect(-6, -1, 8, 2);
      // trailing guts
      ctx.strokeStyle = '#7d0a12';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(-7, 0); ctx.lineTo(-16, 2); ctx.lineTo(-20, -1); ctx.stroke();
    } else {
      // torso and splayed limbs
      ctx.fillStyle = '#1a2017';
      rr(ctx, -7, -5, 12, 10, 3); ctx.fill();
      ctx.fillStyle = c.kind === 'gutted' ? '#4a5738' : '#33412e';
      rr(ctx, -6, -4, 10, 8, 2); ctx.fill();
      ctx.fillStyle = '#6d7c5b';
      ctx.beginPath(); ctx.arc(5, 0, 3.6, 0, TAU); ctx.fill();
      ctx.fillStyle = '#171a12';
      ctx.fillRect(4, -3, 3, 2);
      // arms/legs splayed
      ctx.strokeStyle = '#4d5b42';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(-1, -4); ctx.lineTo(7, -10); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-2, 4); ctx.lineTo(-10, 9); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-5, -3); ctx.lineTo(-13, -6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(-6, 3); ctx.lineTo(-14, 6); ctx.stroke();
      // open belly / ribs
      if (c.kind !== 'ripped') {
        ctx.fillStyle = '#3c0a0e';
        rr(ctx, -5, -2, 6, 4, 1); ctx.fill();
        ctx.fillStyle = '#b3a98a';
        for (let i = 0; i < 3; i++) ctx.fillRect(-4 + i * 2, -1, 1, 2);
        ctx.fillStyle = '#7d0a12';
        ctx.fillRect(-7, 1, 3, 2);
      } else {
        ctx.fillStyle = '#3c0a0e';
        rr(ctx, -4, -2, 5, 4, 1); ctx.fill();
        ctx.strokeStyle = '#8e0d16';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-4, 2); ctx.lineTo(-10, 6); ctx.stroke();
      }
      ctx.fillStyle = '#6d7c5b';
      ctx.fillRect(1, -5, 3, 2);
    }
    // flies
    ctx.globalAlpha = alpha * 0.6;
    ctx.fillStyle = '#0a0a08';
    const t = state.time;
    for (let i = 0; i < 3; i++) {
      ctx.fillRect(Math.sin(t * 4 + i * 2) * 9, Math.cos(t * 3 + i) * 5 - 6, 1, 1);
    }
    ctx.restore();
  }

  function drawPickup(item) {
    const bob = Math.sin(item.bob) * 2;
    shadow(item.x, item.y + 3, 6, 2.5, 0.35);
    ctx.save();
    ctx.translate(Math.round(item.x), Math.round(item.y - 6 + bob));
    if (item.type === 'medkit') {
      ctx.fillStyle = '#0b0d0b';
      rr(ctx, -7, -5, 14, 10, 2); ctx.fill();
      ctx.fillStyle = '#d7d2bd';
      rr(ctx, -6, -4, 12, 8, 1); ctx.fill();
      ctx.fillStyle = '#b31422';
      ctx.fillRect(-1, -3, 3, 6);
      ctx.fillRect(-4, 0, 9, 2);
      ctx.fillStyle = '#7c0a12';
      ctx.fillRect(-6, 3, 12, 1);
    } else {
      ctx.fillStyle = '#1a1a11';
      rr(ctx, -6, -5, 12, 10, 2); ctx.fill();
      ctx.fillStyle = '#c5a43c';
      ctx.fillRect(-5, -4, 10, 8);
      ctx.fillStyle = '#ffe07a';
      ctx.fillRect(-4, -2, 8, 1);
      ctx.fillStyle = '#e9e2cf';
      ctx.fillRect(-1, -6, 2, 2);
      ctx.fillStyle = '#7d0a12';
      ctx.fillRect(-2, 3, 4, 1);
    }
    ctx.restore();
    // glow ring
    ctx.globalAlpha = 0.18 + Math.sin(item.bob * 2) * 0.06;
    ctx.strokeStyle = item.type === 'medkit' ? '#d7ff4a' : '#ffb15c';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(item.x, item.y, 11, 0, TAU); ctx.stroke();
    ctx.globalAlpha = 1;
  }

  function drawGib(g) {
    shadow(g.x, g.y + 2, 3 * g.size, 1.5 * g.size, 0.28);
    ctx.save();
    ctx.translate(Math.round(g.x), Math.round(g.y - g.z));
    ctx.rotate(g.rot);
    const a = clamp(g.life / 2, 0, 1);
    ctx.globalAlpha = a;
    const s = g.size;
    if (g.type === 'meat') {
      ctx.fillStyle = g.color || '#7d0a12';
      ctx.beginPath();
      ctx.moveTo(-3 * s, -1 * s);
      ctx.lineTo(2 * s, -2 * s);
      ctx.lineTo(4 * s, 1 * s);
      ctx.lineTo(0, 3 * s);
      ctx.lineTo(-3 * s, 2 * s);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(255,120,110,0.4)';
      ctx.fillRect(-1, -1, 2, 1);
    } else if (g.type === 'bone') {
      ctx.fillStyle = '#c5b998';
      ctx.fillRect(-4 * s, -1, 8 * s, 2);
      ctx.fillRect(-5 * s, -2, 2, 4);
      ctx.fillRect(3 * s, -2, 2, 4);
    } else if (g.type === 'cloth') {
      ctx.fillStyle = '#2f3d2b';
      ctx.fillRect(-3 * s, -2 * s, 6 * s, 4 * s);
      ctx.fillStyle = '#1b251a';
      ctx.fillRect(-2 * s, 0, 4 * s, 1);
    } else if (g.type === 'tooth') {
      ctx.fillStyle = '#d8d0b3';
      ctx.fillRect(-1, -2, 2, 3);
    } else if (g.type === 'eye') {
      ctx.fillStyle = '#d9d1b2';
      ctx.beginPath(); ctx.arc(0, 0, 2, 0, TAU); ctx.fill();
      ctx.fillStyle = '#a30f1c';
      ctx.fillRect(-1, -1, 2, 2);
    } else if (g.type === 'arm' || g.type === 'leg') {
      const len = (g.type === 'arm' ? 11 : 13) * s;
      ctx.fillStyle = '#5f6e4f';
      rr(ctx, -len / 2, -1.5 * s, len, 3 * s, 1.5); ctx.fill();
      ctx.fillStyle = '#3f4c36';
      ctx.fillRect(-len / 2, s, len, 1);
      ctx.fillStyle = '#6b0710';
      ctx.fillRect(len / 2 - 2, -1, 2, 2);
    } else if (g.type === 'head') {
      ctx.fillStyle = '#0f130e';
      ctx.beginPath(); ctx.arc(0, 0, 4 * s, 0, TAU); ctx.fill();
      ctx.fillStyle = '#6d7c5b';
      ctx.beginPath(); ctx.arc(0, 0, 3.2 * s, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ff3b43';
      ctx.fillRect(1, -1, 1, 1);
      ctx.fillStyle = '#7d0a12';
      ctx.fillRect(-1, 2, 3, 1);
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawParticle(pt) {
    const a = clamp(pt.life / Math.max(0.01, pt.max), 0, 1);
    ctx.globalAlpha = a;
    ctx.fillStyle = pt.color;
    const s = Math.max(1, pt.size || 1);
    if (pt.type === 'smoke' || pt.type === 'mist') {
      ctx.beginPath();
      ctx.arc(pt.x, pt.y - pt.z, s, 0, TAU);
      ctx.fill();
    } else {
      ctx.fillRect((pt.x - s / 2) | 0, (pt.y - pt.z - s / 2) | 0, s, s);
    }
    ctx.globalAlpha = 1;
  }

  // ------------------------------------------------------------
  //  lighting / weather / overlays
  // ------------------------------------------------------------
  function drawLighting(camX, camY) {
    const lc = lightCtx;
    lc.setTransform(1, 0, 0, 1, 0, 0);
    lc.clearRect(0, 0, view.w, view.h);
    lc.fillStyle = 'rgba(4,7,10,0.64)';
    lc.fillRect(0, 0, view.w, view.h);
    lc.globalCompositeOperation = 'destination-out';

    // moon / ambient wash
    const ag = lc.createRadialGradient(view.w * 0.5, view.h * 0.28, 10, view.w * 0.5, view.h * 0.28, Math.max(view.w, view.h) * 0.7);
    ag.addColorStop(0, 'rgba(0,0,0,0.28)');
    ag.addColorStop(0.6, 'rgba(0,0,0,0.1)');
    ag.addColorStop(1, 'rgba(0,0,0,0)');
    lc.fillStyle = ag;
    lc.fillRect(0, 0, view.w, view.h);

    for (const l of CR.lights) {
      const x = l.x - camX, y = l.y - camY;
      if (x < -l.r || y < -l.r || x > view.w + l.r || y > view.h + l.r) continue;
      const flick = l.flicker ? 1 + Math.sin(state.time * 17 + l.seed) * l.flicker + Math.sin(state.time * 6.3 + l.seed) * l.flicker * 0.5 : 1;
      const r = l.r * (0.94 + flick * 0.06);
      const g = lc.createRadialGradient(x, y, 2, x, y, r);
      g.addColorStop(0, `rgba(0,0,0,${0.92 * l.intensity * flick})`);
      g.addColorStop(0.45, `rgba(0,0,0,${0.4 * l.intensity * flick})`);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      lc.fillStyle = g;
      lc.fillRect(x - r, y - r, r * 2, r * 2);
    }

    // player's own light
    const px = player.x - camX, py = player.y - camY;
    const pr = 62 + player.rev * 12;
    const pg = lc.createRadialGradient(px, py, 2, px, py, pr);
    pg.addColorStop(0, 'rgba(0,0,0,0.82)');
    pg.addColorStop(0.5, 'rgba(0,0,0,0.42)');
    pg.addColorStop(1, 'rgba(0,0,0,0)');
    lc.fillStyle = pg;
    lc.fillRect(px - pr, py - pr, pr * 2, pr * 2);

    // chainsaw glow
    if (player.rev > 0.1 && !player.dead) {
      const cx = px + Math.cos(player.aim) * 20;
      const cy = py + Math.sin(player.aim) * 20;
      const cr = 22 + player.rev * 18;
      const cg = lc.createRadialGradient(cx, cy, 1, cx, cy, cr);
      cg.addColorStop(0, 'rgba(0,0,0,0.6)');
      cg.addColorStop(1, 'rgba(0,0,0,0)');
      lc.fillStyle = cg;
      lc.fillRect(cx - cr, cy - cr, cr * 2, cr * 2);
    }

    lc.globalCompositeOperation = 'source-over';
    ctx.drawImage(lightCanvas, 0, 0);

    // additive color pass
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const l of CR.lights) {
      const x = l.x - camX, y = l.y - camY;
      if (x < -l.r || y < -l.r || x > view.w + l.r || y > view.h + l.r) continue;
      const flick = l.flicker ? 0.85 + Math.sin(state.time * 13 + l.seed) * l.flicker : 1;
      const r = l.r * 0.72;
      const [cr, cg, cb] = l.color;
      const g = ctx.createRadialGradient(x, y, 1, x, y, r);
      g.addColorStop(0, `rgba(${cr},${cg},${cb},${0.1 * l.intensity * flick})`);
      g.addColorStop(0.5, `rgba(${cr},${cg},${cb},${0.035 * l.intensity * flick})`);
      g.addColorStop(1, `rgba(${cr},${cg},${cb},0)`);
      ctx.fillStyle = g;
      ctx.fillRect(x - r, y - r, r * 2, r * 2);
    }
    // saw heat
    if (player.rev > 0.1 && !player.dead) {
      const cx = px + Math.cos(player.aim) * 19;
      const cy = py + Math.sin(player.aim) * 19;
      const cr = 18 + player.rev * 15;
      const g = ctx.createRadialGradient(cx, cy, 1, cx, cy, cr);
      const col = player.frenzyTime > 0 ? '255,45,50' : '255,130,45';
      g.addColorStop(0, `rgba(${col},${0.18 + player.rev * 0.14})`);
      g.addColorStop(1, `rgba(${col},0)`);
      ctx.fillStyle = g;
      ctx.fillRect(cx - cr, cy - cr, cr * 2, cr * 2);
    }
    ctx.restore();
  }

  function drawFog(camX, camY) {
    ctx.save();
    for (const f of CR.fog) {
      const x = f.x - camX - 110 * f.s;
      const y = f.y - camY - 55 * f.s;
      if (x < -240 || y < -140 || x > view.w + 240 || y > view.h + 140) continue;
      ctx.globalAlpha = f.a * (0.7 + Math.sin(state.time * 0.2 + f.x) * 0.2);
      ctx.drawImage(CR.fogSprite, x, y, 220 * f.s, 110 * f.s);
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawRain() {
    ctx.save();
    ctx.strokeStyle = '#b8cfc8';
    ctx.lineWidth = 1;
    for (const r of CR.rain) {
      ctx.globalAlpha = r.a;
      ctx.beginPath();
      ctx.moveTo(r.x, r.y);
      ctx.lineTo(r.x - r.len * 0.16, r.y + r.len);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawScreenDrops() {
    ctx.save();
    for (const d of CR.screenDrops) {
      ctx.globalAlpha = clamp(d.life / d.max, 0, 1) * 0.7;
      ctx.fillStyle = '#8b0b14';
      ctx.beginPath();
      ctx.arc(d.x, d.y, d.r, 0, TAU);
      ctx.fill();
      ctx.fillRect(d.x - d.r * 0.4, d.y, d.r * 0.8, d.r * 3);
    }
    ctx.globalAlpha = 1;
    ctx.restore();
  }

  function drawVignette() {
    const g = ctx.createRadialGradient(view.w / 2, view.h / 2, Math.min(view.w, view.h) * 0.25, view.w / 2, view.h / 2, Math.max(view.w, view.h) * 0.72);
    g.addColorStop(0, 'rgba(0,0,0,0)');
    g.addColorStop(0.62, 'rgba(0,0,0,0.12)');
    g.addColorStop(1, 'rgba(0,0,0,0.62)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, view.w, view.h);
    if (player.hp <= 30 && player.hp > 0 && state.mode !== 'menu') {
      const pulse = 0.1 + Math.sin(state.time * 7) * 0.05;
      const rg = ctx.createRadialGradient(view.w / 2, view.h / 2, Math.min(view.w, view.h) * 0.25, view.w / 2, view.h / 2, Math.max(view.w, view.h) * 0.68);
      rg.addColorStop(0, 'rgba(120,0,8,0)');
      rg.addColorStop(1, `rgba(150,0,10,${pulse})`);
      ctx.fillStyle = rg;
      ctx.fillRect(0, 0, view.w, view.h);
    }
  }

  // ------------------------------------------------------------
  //  HUD
  // ------------------------------------------------------------
  function drawHUD() {
    if (state.mode === 'menu') return;
    const t = state.time;

    // left vitals
    panel(8, 8, 118, 48, 0.48);
    drawText(ctx, 'VITALS', 13, 12, { scale: 1, color: '#8f8a7c' });
    const hpPct = clamp(player.hp / player.maxHp, 0, 1);
    const hpColor = hpPct > 0.6 ? '#b31522' : hpPct > 0.3 ? '#d78a22' : '#ff2f39';
    bar(13, 23, 106, 7, hpPct, hpColor);
    // segments
    ctx.fillStyle = 'rgba(6,8,7,0.7)';
    for (let i = 1; i < 14; i++) ctx.fillRect(13 + Math.round(i * 106 / 14), 23, 1, 7);
    drawText(ctx, `${Math.ceil(player.hp)}`, 118, 12, { scale: 1, color: hpPct > 0.3 ? '#e9e2cf' : '#ff5a5f', align: 'right' });

    drawText(ctx, 'DASH', 13, 35, { scale: 1, color: '#716d62' });
    const dashPct = 1 - clamp(player.dashCd / 0.82, 0, 1);
    bar(39, 37, 42, 3, dashPct, dashPct >= 1 ? '#b8d2c2' : '#5e6c62');
    drawText(ctx, 'FRENZY', 13, 43, { scale: 1, color: player.frenzy >= 100 ? '#d7ff4a' : '#716d62' });
    const frPct = clamp(player.frenzy / 100, 0, 1);
    bar(54, 45, 66, 3, frPct, player.frenzyTime > 0 ? '#ff3b43' : frPct >= 1 ? (Math.sin(t * 10) > 0 ? '#d7ff4a' : '#f5ffae') : '#a98c2d');
    if (player.frenzy >= 100 && player.frenzyTime <= 0) {
      drawText(ctx, 'Q', 110, 43, { scale: 1, color: '#d7ff4a', align: 'right' });
    }

    // center wave
    const cx = view.w / 2;
    panel(cx - 65, 8, 130, 30, 0.42);
    drawText(ctx, 'WAVE', cx, 11, { scale: 1, color: '#8f8a7c', align: 'center' });
    drawText(ctx, String(state.wave).padStart(2, '0'), cx, 18, { scale: 2, color: '#e9e2cf', align: 'center' });
    const remain = Math.max(0, state.remaining);
    const total = Math.max(1, remain + state.kills % 10);
    drawText(ctx, state.waveState === 'clear' ? 'CLEARED' : `REMAINING ${String(remain).padStart(2, '0')}`, cx, 35, {
      scale: 1, color: state.waveState === 'clear' ? '#d7ff4a' : '#8f8a7c', align: 'center'
    });

    // right score
    panel(view.w - 126, 8, 118, 42, 0.42);
    drawText(ctx, 'SCORE', view.w - 120, 12, { scale: 1, color: '#8f8a7c' });
    drawText(ctx, String(state.score).padStart(6, '0'), view.w - 13, 12, { scale: 1, color: '#e9e2cf', align: 'right' });
    drawText(ctx, 'KILLS', view.w - 120, 22, { scale: 1, color: '#716d62' });
    drawText(ctx, String(state.kills).padStart(3, '0'), view.w - 13, 22, { scale: 1, color: '#d9b35a', align: 'right' });
    drawText(ctx, 'CHAIN', view.w - 120, 34, { scale: 1, color: '#716d62' });
    drawText(ctx, 'x' + state.combo, view.w - 13, 32, {
      scale: state.combo > 9 ? 2 : 1,
      color: state.combo > 5 ? '#ff5a5f' : state.combo > 1 ? '#ffb15c' : '#716d62',
      align: 'right'
    });
    if (state.combo > 1) {
      const cw = 52;
      const cp = clamp(state.comboTimer / 3.4, 0, 1);
      bar(view.w - 120, 44, cw, 2, cp, state.combo > 5 ? '#ff3b43' : '#c88a2a');
    }

    // boss bar
    if (state.boss && !state.boss.dead) {
      const bw = Math.min(260, view.w - 80);
      const bx = (view.w - bw) / 2;
      drawText(ctx, 'ABATTOIR // THE BIG ONE', view.w / 2, 48, { scale: 1, color: '#ff5a5f', align: 'center' });
      bar(bx, 57, bw, 5, state.boss.hp / state.boss.maxHp, '#b31522', '#2a080b');
    }

    // announcement
    if (state.announce) {
      const a = state.announce;
      const elapsed = a.max - a.time;
      const fadeIn = clamp(elapsed * 5, 0, 1);
      const fadeOut = clamp(a.time * 3, 0, 1);
      const alpha = Math.min(fadeIn, fadeOut);
      const y = view.h * 0.28 - (1 - fadeIn) * 8;
      ctx.globalAlpha = alpha;
      ctx.fillStyle = 'rgba(4,6,7,0.55)';
      ctx.fillRect(0, y - 8, view.w, 40);
      ctx.fillStyle = 'rgba(193,18,31,0.5)';
      ctx.fillRect(0, y - 8, view.w, 1);
      ctx.fillRect(0, y + 31, view.w, 1);
      const scale = Math.min(3, Math.floor((view.w - 30) / Math.max(1, textWidth(a.title, 1))));
      drawText(ctx, a.title, view.w / 2 + 2, y, { scale, color: '#8a0b14', align: 'center', shadow: false });
      drawText(ctx, a.title, view.w / 2, y - 1, { scale, color: '#e9e2cf', align: 'center' });
      drawText(ctx, a.sub, view.w / 2, y + 22, { scale: 1, color: '#d7b45a', align: 'center' });
      ctx.globalAlpha = 1;
    }

    // controls hint
    if (state.mode === 'playing' && state.gameTime < 13) {
      const a = clamp((13 - state.gameTime) / 3, 0, 1);
      ctx.globalAlpha = a * 0.75;
      drawText(ctx, 'WASD MOVE   //   MOUSE AIM   //   HOLD LMB TO RIP   //   SHIFT DASH   //   Q FRENZY', view.w / 2, view.h - 15, {
        scale: 1, color: '#b9b3a2', align: 'center'
      });
      ctx.globalAlpha = 1;
    }

    // status tags
    if (player.frenzyTime > 0) {
      const a = 0.65 + Math.sin(t * 12) * 0.25;
      ctx.globalAlpha = a;
      drawText(ctx, 'BLOOD FRENZY', view.w / 2, view.h - 30, { scale: 2, color: '#ff3b43', align: 'center' });
      ctx.globalAlpha = 1;
    }
  }

  function drawCrosshair() {
    if (state.mode === 'menu' || input.touch.active) return;
    const x = Math.round(input.mouse.x), y = Math.round(input.mouse.y);
    const hot = player.attack || player.rev > 0.25;
    const col = player.frenzyTime > 0 ? '#ff6b6b' : hot ? '#ffb15c' : '#d8d2bf';
    ctx.save();
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = col;
    // four brackets
    const r = 5;
    ctx.fillRect(x - r - 2, y - r, 4, 1);
    ctx.fillRect(x + r - 1, y - r, 4, 1);
    ctx.fillRect(x - r - 2, y + r, 4, 1);
    ctx.fillRect(x + r - 1, y + r, 4, 1);
    ctx.fillRect(x - r, y - r - 2, 1, 4);
    ctx.fillRect(x - r, y + r - 1, 1, 4);
    ctx.fillRect(x + r, y - r - 2, 1, 4);
    ctx.fillRect(x + r, y + r - 1, 1, 4);
    ctx.fillRect(x, y, 1, 1);
    if (hot) {
      ctx.globalAlpha = 0.55;
      ctx.strokeStyle = col;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(x, y, 8, state.time * 9, state.time * 9 + 2.2);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawLowHealthEdges() {
    if (state.mode === 'menu' || player.hp > 30 || player.dead) return;
    const p = 0.16 + Math.sin(state.time * 6.5) * 0.06;
    const g = ctx.createRadialGradient(view.w / 2, view.h / 2, Math.min(view.w, view.h) * 0.28, view.w / 2, view.h / 2, Math.max(view.w, view.h) * 0.66);
    g.addColorStop(0, 'rgba(100,0,5,0)');
    g.addColorStop(1, `rgba(130,0,8,${p})`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, view.w, view.h);
  }

  // ------------------------------------------------------------
  //  master render
  // ------------------------------------------------------------
  CR.render = function () {
    const t = state.time;
    const camX = Math.floor(cam.x - state.shakeX);
    const camY = Math.floor(cam.y - state.shakeY);

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#070a0b';
    ctx.fillRect(0, 0, view.w, view.h);

    const sx = clamp(camX, 0, Math.max(0, world.w - view.w));
    const sy = clamp(camY, 0, Math.max(0, world.h - view.h));
    ctx.drawImage(CR.ground, sx, sy, view.w, view.h, 0, 0, view.w, view.h);
    ctx.drawImage(CR.decals, sx, sy, view.w, view.h, 0, 0, view.w, view.h);

    ctx.save();
    ctx.translate(-camX, -camY);

    // afterimages under everything
    for (const a of CR.afterimages) {
      ctx.save();
      ctx.globalAlpha = (a.life / a.max) * 0.28;
      ctx.translate(a.x, a.y);
      ctx.rotate(a.angle);
      ctx.fillStyle = '#9fd0bc';
      rr(ctx, -8, -7, 14, 14, 4); ctx.fill();
      rr(ctx, 9, -3, 7, 6, 1); ctx.fill();
      ctx.restore();
    }

    // y-sorted scene
    const items = [];
    for (const p of CR.props) {
      if (visible(p.x, p.y, 150)) items.push({ y: p.y, kind: 'prop', v: p });
    }
    for (const c of CR.corpses) {
      if (visible(c.x, c.y, 60)) items.push({ y: c.y, kind: 'corpse', v: c });
    }
    for (const c of CR.decorCorpses) {
      if (visible(c.x, c.y, 60)) items.push({ y: c.y, kind: 'corpse', v: c });
    }
    for (const z of CR.zombies) {
      if (!z.dead && visible(z.x, z.y, 60)) items.push({ y: z.y, kind: 'zombie', v: z });
    }
    for (const item of CR.pickups) {
      if (visible(item.x, item.y, 40)) items.push({ y: item.y, kind: 'pickup', v: item });
    }
    items.push({ y: player.y, kind: 'player', v: player });
    items.sort((a, b) => a.y - b.y);

    for (const item of items) {
      if (item.kind === 'prop') drawProp(item.v, t);
      else if (item.kind === 'zombie') drawZombie(item.v, t);
      else if (item.kind === 'corpse') drawCorpse(item.v);
      else if (item.kind === 'pickup') drawPickup(item.v);
      else if (item.kind === 'player') drawPlayer(item.v, t);
    }

    // gibs and particles sit above the sorted scene
    for (const g of CR.gibs) drawGib(g);
    for (const pt of CR.particles) drawParticle(pt);

    // floating combat text
    for (const f of CR.floaters) {
      const a = clamp(f.life / 0.35, 0, 1);
      ctx.globalAlpha = a;
      drawText(ctx, f.text, f.x, f.y, { scale: f.scale, color: f.color, align: 'center', outline: '#1a0305' });
      ctx.globalAlpha = 1;
    }

    ctx.restore();

    drawLighting(camX, camY);
    drawFog(camX, camY);
    drawRain();
    drawScreenDrops();
    drawLowHealthEdges();

    // white flash
    if (state.whiteFlash > 0.01) {
      ctx.globalAlpha = Math.min(0.55, state.whiteFlash * 0.5);
      ctx.fillStyle = '#d9e6e0';
      ctx.fillRect(0, 0, view.w, view.h);
      ctx.globalAlpha = 1;
    }
    if (state.flash > 0.01) {
      ctx.globalAlpha = Math.min(0.24, state.flash * 0.22);
      ctx.fillStyle = '#ff3b43';
      ctx.fillRect(0, 0, view.w, view.h);
      ctx.globalAlpha = 1;
    }

    drawVignette();
    drawHUD();
    drawCrosshair();
  };
})();

