8:   const TAU = Math.PI * 2;
9:   const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
10:   const lerp = (a, b, t) => a + (b - a) * t;
11:   const rand = (a = 1, b = 0) => b + Math.random() * (a - b);
12:   const randInt = (a, b) => Math.floor(b + Math.random() * (a - b + 1));
13:   const pick = arr => arr[(Math.random() * arr.length) | 0];
14:   const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
15:   const angleDiff = (a, b) => Math.atan2(Math.sin(a - b), Math.cos(a - b));
16:   const approach = (v, target, step) => v < target ? Math.min(v + step, target) : Math.max(v - step, target);
17: 
18:   function mulberry32(a) {
19:     return function () {
20:       a |= 0; a = a + 0x6D2B79F5 | 0;
21:       let t = Math.imul(a ^ a >>> 15, 1 | a);
22:       t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
23:       return ((t ^ t >>> 14) >>> 0) / 4294967296;
24:     };
25:   }
