27:   function rr(c, x, y, w, h, r) {
28:     r = Math.min(r, w / 2, h / 2);
29:     c.beginPath();
30:     c.moveTo(x + r, y);
31:     c.lineTo(x + w - r, y);
32:     c.quadraticCurveTo(x + w, y, x + w, y + r);
33:     c.lineTo(x + w, y + h - r);
34:     c.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
35:     c.lineTo(x + r, y + h);
36:     c.quadraticCurveTo(x, y + h, x, y + h - r);
37:     c.lineTo(x, y + r);
38:     c.quadraticCurveTo(x, y, x + r, y);
39:     c.closePath();
40:   }
41: 
42:   function ellipse(c, x, y, rx, ry, color) {
43:     c.fillStyle = color;
44:     c.beginPath();
45:     c.ellipse(x, y, rx, ry, 0, 0, TAU);
46:     c.fill();
47:   }
