121:   function textWidth(text, scale = 1) {
122:     const s = String(text);
123:     return Math.max(0, s.length * 6 * scale - scale);
124:   }
125: 
126:   function drawText(c, text, x, y, opts = {}) {
127:     const s = String(text).toUpperCase();
128:     const scale = opts.scale || 1;
129:     const color = opts.color || '#e9e2cf';
130:     const align = opts.align || 'left';
131:     const w = textWidth(s, scale);
132:     let px = Math.round(align === 'center' ? x - w / 2 : align === 'right' ? x - w : x);
133:     const py = Math.round(y);
134:     const prevAlpha = c.globalAlpha;
135: 
136:     if (opts.shadow !== false) {
137:       c.globalAlpha = prevAlpha * (opts.shadowAlpha ?? 0.7);
138:       c.fillStyle = opts.shadowColor || '#050607';
139:       drawGlyphs(c, s, px + scale, py + scale, scale);
140:       c.globalAlpha = prevAlpha;
141:     }
142:     c.fillStyle = color;
143:     drawGlyphs(c, s, px, py, scale);
144: 
145:     if (opts.outline) {
146:       c.globalAlpha = prevAlpha * 0.85;
147:       c.fillStyle = opts.outline;
148:       const o = Math.max(1, scale * 0.5);
149:       drawGlyphs(c, s, px - o, py, scale);
150:       drawGlyphs(c, s, px + o, py, scale);
151:       drawGlyphs(c, s, px, py - o, scale);
152:       drawGlyphs(c, s, px, py + o, scale);
153:       c.globalAlpha = prevAlpha;
154:       c.fillStyle = color;
155:       drawGlyphs(c, s, px, py, scale);
156:     }
157:     c.globalAlpha = prevAlpha;
158:   }
159: 
160:   function drawGlyphs(c, s, x, y, scale) {
161:     for (let i = 0; i < s.length; i++) {
162:       const g = FONT[s[i]];
163:       if (!g) {
164:         c.fillRect(x + i * 6 * scale, y, 5 * scale, 7 * scale);
165:         continue;
166:       }
167:       for (let row = 0; row < 7; row++) {
168:         const line = g[row];
169:         for (let col = 0; col < 5; col++) {
170:           if (line[col] === '1') c.fillRect(x + (i * 6 + col) * scale, y + row * scale, scale, scale);
171:         }
172:       }
173:     }
174:   }
