283:   class SoundEngine {
284:     constructor() {
285:       this.ctx = null;
286:       this.master = null;
287:       this.muted = false;
288:       this.started = false;
289:       this.sawGain = null;
290:       this.sawOsc = null;
291:       this.sawOsc2 = null;
292:       this.sawNoiseGain = null;
293:       this.noiseBuf = null;
294:       this.ambient = null;
295:     }
296: 
297:     makeNoise(seconds = 2) {
298:       const c = this.ctx;
299:       const buf = c.createBuffer(1, Math.floor(c.sampleRate * seconds), c.sampleRate);
300:       const data = buf.getChannelData(0);
301:       let last = 0;
302:       for (let i = 0; i < data.length; i++) {
303:         const white = Math.random() * 2 - 1;
304:         last = (last + 0.02 * white) / 1.02;
305:         data[i] = last * 3.5;
306:       }
307:       return buf;
308:     }
309: 
310:     init() {
311:       if (this.ctx) return;
312:       const AC = window.AudioContext || window.webkitAudioContext;
313:       if (!AC) return;
314:       const c = this.ctx = new AC();
315:       this.master = c.createGain();
316:       this.master.gain.value = 0.52;
317:       this.master.connect(c.destination);
318:       this.noiseBuf = this.makeNoise(2.5);
319:       this.buildAmbient();
320:       this.buildSaw();
321:     }
322: 
323:     unlock() {
324:       if (!this.ctx) this.init();
325:       if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
326:     }
327: 
328:     buildAmbient() {
329:       const c = this.ctx;
330:       const ambient = c.createGain();
331:       ambient.gain.value = 0.16;
332:       ambient.connect(this.master);
333: 
334:       const wind = c.createBufferSource();
335:       wind.buffer = this.noiseBuf;
336:       wind.loop = true;
337:       const wf = c.createBiquadFilter();
338:       wf.type = 'lowpass';
339:       wf.frequency.value = 380;
340:       wf.Q.value = 0.7;
341:       const wg = c.createGain();
342:       wg.gain.value = 0.065;
343:       wind.connect(wf).connect(wg).connect(ambient);
344:       wind.start();
345: 
346:       const rain = c.createBufferSource();
347:       rain.buffer = this.noiseBuf;
348:       rain.loop = true;
349:       const rf = c.createBiquadFilter();
350:       rf.type = 'highpass';
351:       rf.frequency.value = 2600;
352:       const rg = c.createGain();
353:       rg.gain.value = 0.018;
354:       rain.connect(rf).connect(rg).connect(ambient);
355:       rain.start();
356: 
357:       [55, 82.5, 110].forEach((f, i) => {
358:         const o = c.createOscillator();
359:         o.type = i === 2 ? 'triangle' : 'sine';
360:         o.frequency.value = f;
361:         const g = c.createGain();
362:         g.gain.value = i === 2 ? 0.007 : 0.014;
363:         o.connect(g).connect(ambient);
364:         o.start();
365:         const lfo = c.createOscillator();
366:         lfo.frequency.value = 0.06 + i * 0.023;
367:         const lg = c.createGain();
368:         lg.gain.value = 0.006;
369:         lfo.connect(lg).connect(g.gain);
370:         lfo.start();
371:       });
372: 
373:       this.ambient = ambient;
374:     }
375: 
376:     buildSaw() {
377:       const c = this.ctx;
378:       const gain = this.sawGain = c.createGain();
379:       gain.gain.value = 0;
380:       const filter = c.createBiquadFilter();
381:       filter.type = 'lowpass';
382:       filter.frequency.value = 760;
383:       filter.Q.value = 3;
384:       gain.connect(filter).connect(this.master);
385: 
386:       const o = this.sawOsc = c.createOscillator();
387:       o.type = 'sawtooth';
388:       o.frequency.value = 42;
389:       const g1 = c.createGain();
390:       g1.gain.value = 0.28;
391:       o.connect(g1).connect(gain);
392:       o.start();
393: 
394:       const o2 = this.sawOsc2 = c.createOscillator();
395:       o2.type = 'square';
396:       o2.frequency.value = 84;
397:       const g2 = c.createGain();
398:       g2.gain.value = 0.08;
399:       o2.connect(g2).connect(gain);
400:       o2.start();
401: 
402:       const n = c.createBufferSource();
403:       n.buffer = this.noiseBuf;
404:       n.loop = true;
405:       const nf = c.createBiquadFilter();
406:       nf.type = 'bandpass';
407:       nf.frequency.value = 1100;
408:       nf.Q.value = 0.8;
409:       const ng = this.sawNoiseGain = c.createGain();
410:       ng.gain.value = 0.18;
411:       n.connect(nf).connect(ng).connect(gain);
412:       n.start();
413:     }
414: 
415:     setMuted(v) {
416:       this.muted = v;
417:       if (this.master) this.master.gain.setTargetAtTime(v ? 0 : 0.52, this.ctx.currentTime, 0.03);
418:     }
419: 
420:     saw(rev, attacking) {
421:       if (!this.ctx || !this.sawGain) return;
422:       const t = this.ctx.currentTime;
423:       const target = this.started ? (0.005 + rev * 0.045 + (attacking ? 0.025 : 0)) : 0;
424:       this.sawGain.gain.setTargetAtTime(target, t, 0.04);
425:       const f = 38 + rev * 34 + (attacking ? 12 : 0);
426:       this.sawOsc.frequency.setTargetAtTime(f, t, 0.06);
427:       this.sawOsc2.frequency.setTargetAtTime(f * 2.02, t, 0.06);
428:       if (this.sawNoiseGain) this.sawNoiseGain.gain.setTargetAtTime(0.1 + rev * 0.16, t, 0.05);
429:     }
430: 
431:     blip(freq, dur, vol, type = 'square', slide = 0) {
432:       if (!this.ctx || this.muted) return;
433:       const c = this.ctx, t = c.currentTime;
434:       const o = c.createOscillator();
435:       o.type = type;
436:       o.frequency.setValueAtTime(freq, t);
437:       if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
438:       const g = c.createGain();
439:       g.gain.setValueAtTime(0.0001, t);
440:       g.gain.exponentialRampToValueAtTime(vol, t + 0.006);
441:       g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
442:       o.connect(g).connect(this.master);
443:       o.start(t); o.stop(t + dur + 0.02);
444:     }
445: 
446:     noiseHit(dur, vol, freq, type = 'lowpass') {
447:       if (!this.ctx || this.muted) return;
448:       const c = this.ctx, t = c.currentTime;
449:       const n = c.createBufferSource();
450:       n.buffer = this.noiseBuf;
451:       const f = c.createBiquadFilter();
452:       f.type = type;
453:       f.frequency.setValueAtTime(freq, t);
454:       f.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.35), t + dur);
455:       const g = c.createGain();
456:       g.gain.setValueAtTime(vol, t);
457:       g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
458:       n.connect(f).connect(g).connect(this.master);
459:       n.start(t); n.stop(t + dur + 0.02);
460:     }
461: 
462:     hit() {
463:       this.noiseHit(0.13, 0.16, 900, 'bandpass');
464:       this.blip(110, 0.1, 0.05, 'sine', -60);
465:     }
466:     splat() {
467:       this.noiseHit(0.26, 0.2, 620);
468:       this.blip(72, 0.18, 0.06, 'sawtooth', -28);
469:     }
470:     dismember() {
471:       this.noiseHit(0.34, 0.24, 420);
472:       this.blip(58, 0.24, 0.07, 'square', -24);
473:     }
474:     growl() {
475:       if (!this.ctx || this.muted) return;
476:       const c = this.ctx, t = c.currentTime;
477:       const o = c.createOscillator();
478:       o.type = 'sawtooth';
479:       o.frequency.setValueAtTime(rand(75, 52), t);
480:       o.frequency.exponentialRampToValueAtTime(rand(42, 32), t + 0.6);
481:       const f = c.createBiquadFilter();
482:       f.type = 'lowpass';
483:       f.frequency.value = 320;
484:       const g = c.createGain();
485:       g.gain.setValueAtTime(0.0001, t);
486:       g.gain.exponentialRampToValueAtTime(0.055, t + 0.05);
487:       g.gain.exponentialRampToValueAtTime(0.0001, t + 0.7);
488:       o.connect(f).connect(g).connect(this.master);
489:       o.start(t); o.stop(t + 0.75);
490:     }
491:     dash() {
492:       this.noiseHit(0.22, 0.12, 1800, 'bandpass');
493:       this.blip(180, 0.16, 0.04, 'sine', 140);
494:     }
