5:     TAU, clamp, lerp, rand, pick, dist, angleDiff, drawText, textWidth, rr,
6:     ctx, view, world, cam, state, player, input
7:   } = CR;
8: 
9:   const lightCanvas = document.createElement('canvas');
10:   const lightCtx = lightCanvas.getContext('2d');
11:   lightCanvas.width = view.w;
12:   lightCanvas.height = view.h;
13: 
14:   CR.onResize = function () {
15:     lightCanvas.width = view.w;
16:     lightCanvas.height = view.h;
17:     CR.buildRain();
18:   };
19: 
20:   // ------------------------------------------------------------
21:   //  small helpers
22:   // ------------------------------------------------------------
23:   function shadow(x, y, rx, ry, a = 0.38) {
24:     ctx.globalAlpha = a;
25:     ctx.fillStyle = '#040605';
26:     ctx.beginPath();
27:     ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
28:     ctx.fill();
29:     ctx.globalAlpha = 1;
30:   }
31: 
32:   function visible(x, y, margin = 90) {
33:     return x > cam.x - margin && x < cam.x + view.w + margin &&
34:       y > cam.y - margin && y < cam.y + view.h + margin;
35:   }
36: 
37:   function panel(x, y, w, h, a = 0.52) {
38:     ctx.fillStyle = `rgba(5,8,9,${a})`;
39:     ctx.fillRect(x, y, w, h);
40:     ctx.fillStyle = 'rgba(233,226,207,0.08)';
41:     ctx.fillRect(x, y, w, 1);
42:   }
43: 
44:   function bar(x, y, w, h, pct, color, bg = '#1b1d1a') {
45:     ctx.fillStyle = '#050706';
46:     ctx.fillRect(x - 1, y - 1, w + 2, h + 2);
47:     ctx.fillStyle = bg;
48:     ctx.fillRect(x, y, w, h);
49:     const fw = Math.round(w * clamp(pct, 0, 1));
50:     ctx.fillStyle = color;
51:     ctx.fillRect(x, y, fw, h);
52:     ctx.fillStyle = 'rgba(255,255,255,0.22)';
53:     ctx.fillRect(x, y, fw, 1);
54:   }
