56:   // ------------------------------------------------------------
57:   //  props
58:   // ------------------------------------------------------------
59:   function drawProp(p, t) {
60:     const spr = p.sprite;
61:     if (!spr) return;
62:     const sw = spr.width, sh = spr.height;
63:     const ox = Math.round(p.x - sw / 2);
64:     let oy;
65:     if (p.oy === 1) oy = Math.round(p.y - sh + 4);
66:     else if (p.oy === 0.5) oy = Math.round(p.y - sh / 2);
67:     else oy = Math.round(p.y - sh);
68: 
69:     if (p.type === 'pine' || p.type === 'deadTree') {
70:       shadow(p.x + 10, p.y + 3, 26, 8, 0.32);
71:     } else if (p.type === 'truck') {
72:       shadow(p.x + 3, p.y + 10, 61, 15, 0.38);
73:     } else if (p.type === 'dumpster') {
74:       shadow(p.x + 2, p.y + 8, 43, 12, 0.38);
75:     } else if (p.type === 'lamp') {
76:       shadow(p.x + 2, p.y + 2, 9, 3, 0.34);
77:     } else if (p.type === 'meatframe') {
78:       shadow(p.x + 3, p.y + 1, 22, 6, 0.3);
79:     } else {
80:       shadow(p.x + 2, p.y + 4, sw * 0.3, sh * 0.14, 0.3);
81:     }
82: 
83:     ctx.drawImage(spr, ox, oy);
84: 
85:     if (p.type === 'firebarrel') drawFireBarrel(p, t);
86:     if (p.type === 'lamp') drawLampGlow(p, t);
87:     if (p.type === 'truck') {
88:       // weak headlight bloom, kept subtle
89:       ctx.globalAlpha = 0.16;
90:       ctx.fillStyle = '#e7cf86';
91:       ctx.fillRect(p.x + 62, p.y - 8, 6, 2);
92:       ctx.fillRect(p.x + 62, p.y + 5, 6, 2);
93:       ctx.globalAlpha = 1;
94:     }
95:   }
96: 
97:   function drawFireBarrel(p, t) {
98:     const x = Math.round(p.x), y = Math.round(p.y - 20);
99:     const flick = Math.sin(t * 13 + p.x) * 0.5 + 0.5;
100:     for (let i = 0; i < 5; i++) {
101:       const h = 4 + Math.sin(t * (9 + i) + i * 2.1) * 3 + flick * 3;
102:       const ox = Math.sin(t * 7 + i * 1.7) * 3;
103:       ctx.globalAlpha = 0.85 - i * 0.12;
104:       ctx.fillStyle = i < 2 ? '#ffd166' : i < 4 ? '#ff8a2b' : '#c33b17';
105:       ctx.fillRect(x - 4 + i * 2 + ox, y - h, 2, h + 2);
106:     }
107:     ctx.globalAlpha = 0.35 + flick * 0.25;
108:     ctx.fillStyle = '#ffb347';
109:     ctx.fillRect(x - 5, y - 2, 10, 2);
110:     ctx.globalAlpha = 1;
111:     // embers
112:     for (let i = 0; i < 3; i++) {
113:       const yy = (t * (12 + i * 5) + i * 31) % 38;
114:       ctx.globalAlpha = (1 - yy / 38) * 0.7;
115:       ctx.fillStyle = i % 2 ? '#ffd166' : '#ff6b1a';
116:       ctx.fillRect(x + Math.sin(t * 2 + i * 4) * 7, y - yy, 1, 1);
117:     }
118:     ctx.globalAlpha = 1;
119:   }
120: 
121:   function drawLampGlow(p, t) {
122:     const x = p.x - 8, y = p.y - 76;
123:     const flick = 0.86 + Math.sin(t * 17 + p.x) * 0.04 + Math.sin(t * 2.7) * 0.03;
124:     ctx.save();
125:     ctx.globalCompositeOperation = 'lighter';
126:     const g = ctx.createRadialGradient(x, y, 1, x, y, 26);
127:     g.addColorStop(0, `rgba(255,224,157,${0.36 * flick})`);
128:     g.addColorStop(0.4, `rgba(255,186,94,${0.12 * flick})`);
129:     g.addColorStop(1, 'rgba(255,170,70,0)');
130:     ctx.fillStyle = g;
131:     ctx.fillRect(x - 30, y - 30, 60, 60);
132:     ctx.restore();
133:   }
134: 
135:   // ------------------------------------------------------------
136:   //  player
137:   // ------------------------------------------------------------
138:   function drawPlayer(p, t) {
139:     if (p.dead) {
140:       drawPlayerCorpse(p);
141:       return;
142:     }
143:     const px = Math.round(p.x), py = Math.round(p.y);
144:     shadow(px + 1, py + 4, 13, 5, 0.5);
145: 
146:     // frenzy aura
147:     if (p.frenzyTime > 0) {
148:       ctx.save();
149:       ctx.globalCompositeOperation = 'lighter';
150:       const g = ctx.createRadialGradient(px, py, 3, px, py, 30);
151:       g.addColorStop(0, 'rgba(255,40,40,0.16)');
152:       g.addColorStop(0.55, 'rgba(190,10,20,0.09)');
153:       g.addColorStop(1, 'rgba(120,0,10,0)');
154:       ctx.fillStyle = g;
155:       ctx.fillRect(px - 32, py - 32, 64, 64);
156:       ctx.restore();
157:     }
158: 
159:     // attack arc, world-space
160:     if (p.attack && p.rev > 0.2) {
161:       const frenzy = p.frenzyTime > 0;
162:       const range = 30 + p.rev * 5 + (frenzy ? 7 : 0);
163:       const sweep = 0.9 + (frenzy ? 0.22 : 0);
164:       const pulse = 0.18 + Math.abs(Math.sin(t * 24)) * 0.18;
165:       ctx.save();
166:       ctx.translate(px, py);
167:       ctx.rotate(p.aim);
168:       ctx.globalCompositeOperation = 'lighter';
169:       ctx.strokeStyle = `rgba(255,138,43,${pulse})`;
170:       ctx.lineWidth = 2;
171:       ctx.beginPath();
172:       ctx.arc(0, 0, range, -sweep, sweep);
173:       ctx.stroke();
174:       ctx.strokeStyle = `rgba(255,232,168,${pulse * 0.65})`;
175:       ctx.lineWidth = 1;
176:       ctx.beginPath();
177:       ctx.arc(0, 0, range - 3, -sweep * 0.8, sweep * 0.8);
178:       ctx.stroke();
179:       // slash flick
180:       const a = -sweep + ((t * 7) % 1) * sweep * 2;
181:       ctx.fillStyle = `rgba(255,210,120,${0.2 + pulse})`;
182:       ctx.fillRect(Math.cos(a) * (range - 1), Math.sin(a) * (range - 1) - 1, 3, 2);
183:       ctx.restore();
184:     }
185: 
186:     ctx.save();
187:     ctx.translate(px, py);
188:     ctx.rotate(p.aim);
189:     const walking = p.moving || p.dashTime > 0;
190:     const walk = walking ? Math.sin(p.walkPhase) : Math.sin(t * 2) * 0.2;
191:     const bob = walking ? Math.abs(Math.sin(p.walkPhase)) * 0.9 : Math.sin(t * 2) * 0.35;
192:     ctx.translate(0, -bob);
193: 
194:     // trailing legs
195:     drawBoot(-7 + walk * 2.4, -4, '#161b17', '#2a342c');
196:     drawBoot(-7 - walk * 2.4, 4, '#121713', '#232d26');
197: 
198:     // backpack
199:     ctx.fillStyle = '#0b100e';
200:     rr(ctx, -11, -5, 6, 10, 2); ctx.fill();
201:     ctx.fillStyle = '#393326';
202:     rr(ctx, -10, -4, 4, 8, 1); ctx.fill();
203:     ctx.fillStyle = '#17130e';
204:     ctx.fillRect(-10, -2, 4, 1);
205:     ctx.fillRect(-10, 2, 4, 1);
206: 
207:     // torso outline and jacket
208:     ctx.fillStyle = '#0a0f0d';
209:     rr(ctx, -8, -7, 14, 14, 4); ctx.fill();
210:     ctx.fillStyle = '#243c35';
211:     rr(ctx, -7, -6, 12, 12, 3); ctx.fill();
212:     ctx.fillStyle = '#355449';
213:     ctx.fillRect(-6, -6, 7, 1);
214:     ctx.fillRect(-6, -5, 3, 1);
215:     ctx.fillStyle = '#1a2c27';
216:     ctx.fillRect(-5, 4, 8, 2);
217:     // belt
218:     ctx.fillStyle = '#151712';
219:     ctx.fillRect(-3, -7, 2, 14);
220:     ctx.fillStyle = '#a58c4d';
221:     ctx.fillRect(-3, -1, 2, 2);
222:     // blood on jacket
223:     ctx.globalAlpha = 0.55;
224:     ctx.fillStyle = '#6c0710';
225:     ctx.fillRect(-4, 2, 4, 2);
226:     ctx.fillRect(2, -5, 2, 3);
227:     ctx.globalAlpha = 1;
228: 
229:     // shoulder pads
230:     ctx.fillStyle = '#0d1512';
231:     rr(ctx, -3, -8, 6, 3, 1); ctx.fill();
232:     rr(ctx, -3, 5, 6, 3, 1); ctx.fill();
233:     ctx.fillStyle = '#3b564a';
234:     ctx.fillRect(-2, -8, 4, 1);
235:     ctx.fillRect(-2, 7, 4, 1);
236: 
237:     // arms
238:     const armBend = p.attack ? 1 : 0;
239:     ctx.strokeStyle = '#1b2d28';
240:     ctx.lineWidth = 4;
241:     ctx.lineCap = 'butt';
242:     ctx.beginPath();
243:     ctx.moveTo(2, -5);
244:     ctx.lineTo(8 + armBend, -2.5);
245:     ctx.stroke();
246:     ctx.beginPath();
247:     ctx.moveTo(2, 5);
248:     ctx.lineTo(8 + armBend, 2.5);
249:     ctx.stroke();
250:     ctx.strokeStyle = '#4a6658';
251:     ctx.lineWidth = 1;
252:     ctx.beginPath(); ctx.moveTo(2, -6); ctx.lineTo(8, -3); ctx.stroke();
253:     ctx.beginPath(); ctx.moveTo(2, 4); ctx.lineTo(8, 1); ctx.stroke();
254:     // hands
255:     ctx.fillStyle = '#5f4b36';
256:     ctx.fillRect(8 + armBend, -4, 3, 3);
257:     ctx.fillRect(8 + armBend, 1, 3, 3);
258: 
259:     // chainsaw
260:     drawChainsaw(p, t, armBend);
261: 
262:     // head / gas mask
263:     ctx.fillStyle = '#0b110e';
264:     ctx.beginPath(); ctx.arc(4, 0, 5.5, 0, TAU); ctx.fill();
265:     ctx.fillStyle = '#1c2b24';
266:     ctx.beginPath(); ctx.arc(4, 0, 4.6, 0, TAU); ctx.fill();
267:     ctx.fillStyle = '#576553';
268:     ctx.beginPath(); ctx.arc(5.4, 0, 3.8, 0, TAU); ctx.fill();
269:     // lenses
270:     ctx.fillStyle = '#0a0d0a';
271:     ctx.fillRect(6, -2, 3, 2);
272:     ctx.fillRect(6, 1, 3, 2);
273:     ctx.fillStyle = '#d6e58c';
274:     ctx.fillRect(7, -2, 1, 1);
275:     ctx.fillRect(7, 2, 1, 1);
276:     // filter
277:     ctx.fillStyle = '#2d372f';
278:     ctx.fillRect(8, -1, 3, 2);
279:     ctx.fillStyle = '#0b100d';
280:     ctx.fillRect(9, -1, 1, 2);
281:     // hood highlights
282:     ctx.fillStyle = '#31443a';
283:     ctx.fillRect(1, -4, 2, 1);
284:     ctx.fillRect(1, 3, 2, 1);
285: 
286:     // hit flash
287:     if (p.hurtFlash > 0) {
288:       ctx.globalAlpha = p.hurtFlash * 0.4;
289:       ctx.fillStyle = '#ff202b';
290:       ctx.beginPath(); ctx.arc(0, 0, 14, 0, TAU); ctx.fill();
291:       ctx.globalAlpha = 1;
292:     }
293: 
294:     // dash afterimage streaks
295:     if (p.dashTime > 0) {
296:       ctx.globalAlpha = 0.4;
297:       ctx.strokeStyle = '#b8d2c2';
298:       ctx.lineWidth = 1;
299:       for (let i = 0; i < 3; i++) {
300:         ctx.beginPath();
301:         ctx.moveTo(-14 - i * 5, -4 + i * 4);
302:         ctx.lineTo(-25 - i * 5, -4 + i * 4);
303:         ctx.stroke();
304:       }
305:       ctx.globalAlpha = 1;
306:     }
307: 
308:     ctx.restore();
309:   }
310: 
311:   function drawBoot(x, y, c1, c2) {
312:     ctx.fillStyle = c1;
313:     rr(ctx, x - 3, y - 2, 7, 4, 1); ctx.fill();
314:     ctx.fillStyle = c2;
315:     ctx.fillRect(x - 2, y - 2, 4, 1);
316:     ctx.fillStyle = '#070908';
317:     ctx.fillRect(x + 2, y + 1, 2, 1);
318:   }
319: 
320:   function drawChainsaw(p, t, armBend) {
321:     const sx = 9 + armBend + p.swing * 1.2;
322:     const rev = p.rev;
323:     const phase = p.bladePhase;
324: 
325:     // glow / heat
326:     if (rev > 0.15) {
327:       ctx.globalAlpha = 0.12 + rev * 0.13;
328:       ctx.fillStyle = p.frenzyTime > 0 ? '#ff3038' : '#ff8a2b';
329:       ctx.fillRect(sx - 2, -6, 8, 12);
330:       ctx.globalAlpha = 1;
331:     }
332: 
333:     // rear handle
334:     ctx.fillStyle = '#0b0d0b';
335:     rr(ctx, sx - 2, -7, 6, 3, 1); ctx.fill();
336:     ctx.fillRect(sx - 1, -5, 2, 2);
337: 
338:     // engine body
339:     ctx.fillStyle = '#1a0c08';
340:     rr(ctx, sx, -4, 7, 8, 1); ctx.fill();
341:     ctx.fillStyle = '#8d2d12';
342:     rr(ctx, sx + 1, -3, 5, 6, 1); ctx.fill();
343:     ctx.fillStyle = '#d85e1c';
344:     ctx.fillRect(sx + 1, -3, 5, 2);
345:     ctx.fillStyle = '#f08a35';
346:     ctx.fillRect(sx + 2, -3, 2, 1);
347:     ctx.fillStyle = '#3a140c';
348:     ctx.fillRect(sx + 2, 1, 3, 2);
349:     // pull start
350:     ctx.fillStyle = '#15110c';
351:     ctx.fillRect(sx + 1, 4, 3, 2);
352:     // tiny brand slash
353:     ctx.fillStyle = '#ffcf7a';
354:     ctx.fillRect(sx + 4, 0, 1, 2);
355: 
356:     // blade
357:     const bx = sx + 7;
358:     const blen = 18;
359:     ctx.fillStyle = '#151817';
360:     ctx.fillRect(bx, -2, blen, 4);
361:     ctx.fillStyle = '#858c86';
362:     ctx.fillRect(bx, -1.5, blen, 3);
363:     ctx.fillStyle = '#b9c0b7';
364:     ctx.fillRect(bx, -1, blen - 2, 1);
365:     ctx.fillStyle = '#3d433f';
366:     ctx.fillRect(bx, 1, blen, 1);
367: 
368:     // chain teeth
369:     const off = Math.floor(phase) % 4;
370:     ctx.fillStyle = '#dce0d2';
371:     for (let i = 0; i < blen; i += 2) {
372:       if ((i + off) % 4 === 0) {
373:         ctx.fillRect(bx + i, -3, 1, 1);
374:         ctx.fillRect(bx + i + 1, 2, 1, 1);
375:       }
376:     }
377:     // cutting glint
378:     if (rev > 0.5) {
379:       ctx.globalAlpha = 0.3 + Math.sin(t * 30) * 0.2;
380:       ctx.fillStyle = '#fff2c4';
381:       ctx.fillRect(bx + 1, -2, blen - 4, 1);
382:       ctx.globalAlpha = 1;
383:     }
384: 
385:     // guard
386:     ctx.fillStyle = '#242822';
387:     ctx.fillRect(bx - 1, -4, 2, 8);
388:     ctx.fillStyle = '#5a6159';
389:     ctx.fillRect(bx - 1, -4, 1, 8);
390: 
391:     // motion streaks
392:     if (rev > 0.3) {
393:       ctx.globalAlpha = 0.18 + rev * 0.14;
394:       ctx.fillStyle = '#ffd166';
395:       ctx.fillRect(bx + 2, -5, blen - 3, 1);
396:       ctx.fillRect(bx + 1, 4, blen - 2, 1);
397:       ctx.globalAlpha = 1;
398:     }
399:   }
400: 
401:   function drawPlayerCorpse(p) {
402:     ctx.save();
403:     ctx.translate(Math.round(p.x), Math.round(p.y));
404:     ctx.rotate(p.aim);
405:     shadow(0, 4, 13, 5, 0.4);
406:     ctx.fillStyle = '#1a2b26';
407:     rr(ctx, -9, -5, 15, 10, 3); ctx.fill();
408:     ctx.fillStyle = '#0d1411';
409:     rr(ctx, -12, -3, 6, 7, 2); ctx.fill();
410:     ctx.fillStyle = '#4e5d4d';
411:     ctx.beginPath(); ctx.arc(5, 0, 4, 0, TAU); ctx.fill();
412:     ctx.fillStyle = '#0b100d';
413:     ctx.fillRect(5, -2, 3, 2);
414:     ctx.fillStyle = '#6b0710';
415:     ctx.globalAlpha = 0.6;
416:     ctx.fillRect(-6, -2, 9, 4);
417:     ctx.restore();
418:   }
419: 
420:   // ------------------------------------------------------------
421:   //  zombies
422:   // ------------------------------------------------------------
423:   function drawZombie(z, t) {
424:     const px = Math.round(z.x), py = Math.round(z.y);
425:     const s = z.scale;
426:     shadow(px + 1, py + 3, 9 * s, 4 * s, 0.42);
427: 
428:     ctx.save();
429:     ctx.translate(px, py);
430:     ctx.rotate(z.angle);
431:     const walk = Math.sin(t * (z.type === 'runner' ? 11 : 5.5) + z.seed);
432:     const bob = Math.abs(walk) * 0.7;
433:     ctx.translate(0, -bob);
434:     ctx.scale(s, s);
435: 
436:     const skin = z.boss ? '#7a7654' : z.type === 'runner' ? '#798264' : '#6d7c5b';
437:     const skinDark = z.boss ? '#4f4b35' : '#4d5b42';
438:     const shirt = z.type === 'runner' ? '#3c2c2a' : z.boss ? '#2d2520' : '#33412e';
439:     const shirtDark = z.type === 'runner' ? '#241b1a' : z.boss ? '#1c1714' : '#202b1e';
440: 
441:     // legs
442:     drawZLeg(-5 + walk * 2.2, -3, skinDark, skin);
443:     drawZLeg(-5 - walk * 2.2, 3, skinDark, skin);
444:     if (z.boss) {
445:       // heavy feet
446:       ctx.fillStyle = '#17140f';
447:       ctx.fillRect(-9, -6, 5, 3);
448:       ctx.fillRect(-9, 3, 5, 3);
449:     }
450: 
451:     // torso
452:     ctx.fillStyle = '#0c100c';
453:     rr(ctx, -7, -6, 13, 12, 3); ctx.fill();
454:     ctx.fillStyle = shirt;
455:     rr(ctx, -6, -5, 11, 10, 2); ctx.fill();
456:     ctx.fillStyle = shirtDark;
457:     ctx.fillRect(-5, 2, 9, 2);
458:     // exposed chest / ribs
459:     ctx.fillStyle = skinDark;
460:     rr(ctx, 0, -3, 4, 5, 1); ctx.fill();
461:     ctx.fillStyle = '#a49b7d';
462:     for (let i = 0; i < 3; i++) ctx.fillRect(1, -2 + i * 2, 3, 1);
463:     // blood
464:     ctx.globalAlpha = 0.6;
465:     ctx.fillStyle = '#690710';
466:     ctx.fillRect(-4, -4, 3, 2);
467:     ctx.fillRect(-1, 2, 4, 1);
468:     ctx.globalAlpha = 1;
469: 
470:     // arms
471:     if (z.limbs.armL) {
472:       drawZArm(1, -5, walk, skin, skinDark, false);
473:     } else {
474:       drawStump(1, -5, skinDark);
475:     }
476:     if (z.limbs.armR) {
477:       drawZArm(1, 5, -walk, skin, skinDark, true);
478:     } else {
479:       drawStump(1, 5, skinDark);
480:     }
481: 
482:     // neck + head
483:     if (z.limbs.head) {
484:       ctx.fillStyle = '#11150f';
485:       ctx.beginPath(); ctx.arc(5, 0, 5.2, 0, TAU); ctx.fill();
486:       ctx.fillStyle = skin;
487:       ctx.beginPath(); ctx.arc(5.2, 0, 4.4, 0, TAU); ctx.fill();
488:       ctx.fillStyle = skinDark;
489:       ctx.fillRect(3, -4, 3, 2);
490:       // hair / scalp
491:       ctx.fillStyle = z.boss ? '#17130e' : '#23251b';
492:       ctx.fillRect(2, -4, 4, 3);
493:       ctx.fillRect(1, -2, 2, 2);
494:       // jaw / mouth
495:       ctx.fillStyle = '#24120f';
496:       ctx.fillRect(7, 1, 3, 2);
497:       ctx.fillStyle = '#b9ae8d';
498:       ctx.fillRect(8, 1, 1, 1);
499:       // eyes
500:       const eye = z.type === 'runner' ? '#ff3b43' : z.boss ? '#ff9a2b' : '#d6cf74';
501:       ctx.fillStyle = eye;
502:       ctx.fillRect(6, -2, 2, 1);
503:       ctx.fillRect(6, 2, 2, 1);
504:       ctx.fillStyle = 'rgba(255,80,60,0.35)';
505:       ctx.fillRect(6, -2, 3, 1);
506:       // wounds
507:       ctx.globalAlpha = 0.55;
508:       ctx.fillStyle = '#5b070d';
509:       ctx.fillRect(4, 3, 2, 2);
510:       ctx.globalAlpha = 1;
511:       if (z.type === 'brute' || z.boss) {
512:         // bone spikes / butcher apron
