382:   function makePine(seed) {
383:     const R = mulberry32(seed);
384:     return make(112, 146, (c) => {
385:       c.fillStyle = '#0a0d0a';
386:       c.fillRect(52, 92, 9, 50);
387:       c.fillStyle = '#2a2116';
388:       c.fillRect(54, 92, 5, 50);
389:       c.fillStyle = '#3a2c1c';
390:       c.fillRect(55, 93, 1, 44);
391:       const layers = [
392:         { y: 88, w: 54, h: 34, col: '#101b12' },
393:         { y: 68, w: 48, h: 38, col: '#142217' },
394:         { y: 45, w: 39, h: 36, col: '#18291b' },
395:         { y: 23, w: 28, h: 30, col: '#1d3120' },
396:         { y: 5, w: 16, h: 26, col: '#233a25' }
397:       ];
398:       for (const L of layers) {
399:         c.fillStyle = L.col;
400:         c.beginPath();
401:         c.moveTo(56, L.y);
402:         c.lineTo(56 - L.w, L.y + L.h);
403:         c.lineTo(56 - L.w * 0.58, L.y + L.h * 0.74);
404:         c.lineTo(56 - L.w * 0.38, L.y + L.h);
405:         c.lineTo(56, L.y + L.h * 0.8);
406:         c.lineTo(56 + L.w * 0.38, L.y + L.h);
407:         c.lineTo(56 + L.w * 0.58, L.y + L.h * 0.74);
408:         c.lineTo(56 + L.w, L.y + L.h);
409:         c.closePath();
410:         c.fill();
411:       }
412:       // needle clusters / moonlight rim
413:       for (let i = 0; i < 90; i++) {
414:         const y = R() * 100;
415:         const spread = (y / 100) * 46 + 6;
416:         const x = 56 + (R() * 2 - 1) * spread;
417:         c.globalAlpha = R() * 0.35 + 0.08;
418:         c.fillStyle = R() > 0.5 ? '#375438' : '#0a120c';
419:         c.fillRect(x | 0, y | 0, R() > 0.7 ? 2 : 1, 1);
420:       }
421:       c.globalAlpha = 1;
422:     });
423:   }
