425:   function makeDeadTree(seed) {
426:     const R = mulberry32(seed);
427:     return make(94, 124, (c) => {
428:       c.strokeStyle = '#17140f';
429:       c.lineWidth = 7;
430:       c.lineCap = 'round';
431:       c.beginPath();
432:       c.moveTo(48, 121);
433:       c.lineTo(47, 88);
434:       c.lineTo(51, 56);
435:       c.lineTo(44, 33);
436:       c.stroke();
437:       c.strokeStyle = '#2c2518';
438:       c.lineWidth = 3;
439:       c.beginPath();
440:       c.moveTo(49, 120);
441:       c.lineTo(48, 88);
442:       c.lineTo(51, 56);
443:       c.lineTo(45, 34);
444:       c.stroke();
445:       const branches = [
446:         [48, 88, 26, 68], [48, 76, 70, 55], [50, 61, 24, 42],
447:         [46, 48, 68, 28], [44, 36, 25, 20], [52, 54, 82, 44]
448:       ];
449:       for (const b of branches) {
450:         c.strokeStyle = '#17140f';
451:         c.lineWidth = 4;
452:         c.beginPath(); c.moveTo(b[0], b[1]); c.quadraticCurveTo((b[0] + b[2]) / 2 + R() * 8 - 4, (b[1] + b[3]) / 2, b[2], b[3]); c.stroke();
453:         c.strokeStyle = '#332a1a';
454:         c.lineWidth = 1;
455:         c.beginPath(); c.moveTo(b[0], b[1]); c.quadraticCurveTo((b[0] + b[2]) / 2, (b[1] + b[3]) / 2, b[2], b[3]); c.stroke();
456:         for (let i = 0; i < 3; i++) {
457:           c.strokeStyle = '#211b12';
458:           c.lineWidth = 1;
459:           c.beginPath();
460:           c.moveTo(b[2], b[3]);
461:           c.lineTo(b[2] + (R() * 2 - 1) * 16, b[3] - R() * 14);
462:           c.stroke();
463:         }
464:       }
465:       // roots
466:       c.strokeStyle = '#211b12';
467:       c.lineWidth = 2;
468:       for (let i = 0; i < 5; i++) {
469:         c.beginPath();
470:         c.moveTo(48, 120);
471:         c.lineTo(48 + (R() * 2 - 1) * 22, 121 + R() * 2);
472:         c.stroke();
473:       }
474:       // crows / knots
475:       c.fillStyle = '#0b0a08';
476:       c.fillRect(44, 52, 3, 2);
477:       c.fillRect(29, 68, 2, 2);
478:     });
479:   }
