572:   function updateZombies(dt) {
573:     const p = player;
574:     const list = CR.zombies;
575:     for (const z of list) {
576:       if (z.dead) continue;
577:       z.flash = Math.max(0, z.flash - dt);
578:       z.swipe = Math.max(0, z.swipe - dt);
579:       z.growlCd -= dt;
580:       if (z.growlCd <= 0) {
581:         z.growlCd = rand(4, 10);
582:         if (Math.random() < 0.4 && CR.sound) CR.sound.growl();
583:       }
584: 
585:       if (z.stagger > 0) {
586:         z.stagger -= dt;
587:         z.x += z.vx * dt;
588:         z.y += z.vy * dt;
589:         z.vx *= Math.pow(0.001, dt);
590:         z.vy *= Math.pow(0.001, dt);
591:         CR.resolveProps(z);
592:         continue;
593:       }
594: 
595:       const dx = p.x - z.x, dy = p.y - z.y;
596:       const d = Math.hypot(dx, dy) || 1;
597:       let target = Math.atan2(dy, dx);
598:       const wobble = Math.sin(state.time * 1.7 + z.seed) * (z.type === 'runner' ? 0.14 : 0.34);
599:       target += wobble;
600:       z.angle += angleDiff(target, z.angle) * Math.min(1, dt * (z.type === 'runner' ? 7 : 3.8));
601: 
602:       const minD = z.radius + p.radius + 2;
603:       if (d > minD + 1 && !p.dead && state.mode !== 'menu') {
604:         let sp = z.speed * z.slow;
605:         if (z.type === 'runner') sp *= 0.9 + Math.sin(state.time * 6 + z.seed) * 0.15;
606:         z.x += Math.cos(z.angle) * sp * dt;
607:         z.y += Math.sin(z.angle) * sp * dt;
608:       } else if (state.mode === 'menu') {
609:         z.x += Math.cos(z.angle + Math.PI / 2) * z.speed * 0.25 * dt;
610:         z.y += Math.sin(z.angle + Math.PI / 2) * z.speed * 0.25 * dt;
611:       }
612: 
613:       // attack
614:       if (state.mode === 'playing' && !p.dead) {
615:         z.attackCd -= dt;
616:         if (d < minD + 7 && z.attackCd <= 0) {
617:           z.attackCd = z.type === 'runner' ? 0.95 : z.type === 'brute' ? 1.55 : 1.35;
618:           z.swipe = 0.32;
619:           if (p.invuln <= 0) {
620:             damagePlayer(z.damage, Math.atan2(p.y - z.y, p.x - z.x), z);
621:           }
622:         }
623:       }
624: 
625:       // crowd separation
626:       for (const o of list) {
627:         if (o === z || o.dead) continue;
628:         const ox = z.x - o.x, oy = z.y - o.y;
629:         const od = Math.hypot(ox, oy);
630:         const min = z.radius + o.radius - 1;
631:         if (od < min && od > 0.001) {
632:           const push = (min - od) / od * 0.5;
633:           z.x += ox * push;
634:           z.y += oy * push;
635:         }
636:       }
637: 
638:       CR.resolveProps(z);
639:     }
640:   }
